} from "./happyAgentTypes.js";

const WORKING_LABEL_MAX = 64;
const SENT_IMAGE_BUDGET_BYTES = 32 * 1024 * 1024;
const PENDING_MUTATION_LIMIT = 2_048;
/** Keep a released store alive long enough to surface a slow mutation refusal. */
const PENDING_MUTATION_RETENTION_MS = 2 * 60_000;

function transcriptSessionBusy(session: SessionState): boolean {
    return session.activeTurn !== undefined;
}

function waitingForModelProject(
    session: SessionState | undefined,
    elements: readonly ChatElement[] | undefined,
    runStatus: HappyAgentChatSnapshot["runStatus"],
): boolean {
    if (runStatus !== "running" || session === undefined || elements === undefined) return false;
    const activeGroup = session.activeGroup;
    if (activeGroup !== undefined) {
        const activeElement = elements.find(
            (element) => element.groupId === activeGroup.groupId && !chatElementRequest(element),
        );
        return activeElement?.kind === "inference";
    }
    const activeTurn = session.activeTurn;
    if (activeTurn === undefined) return false;
    const produced = elements.some(
        (element) =>
            element.runId === activeTurn.runId &&
            !chatElementRequest(element) &&
            element.kind !== "inference" &&
            element.kind !== "group_end",
    );
    if (produced) return false;
    return (
        session.activity.kind === "idle" ||
        session.activity.kind === "queued" ||
        session.activity.kind === "thinking"
    );
}

function workingPhaseProject(
    session: SessionState | undefined,
    waitingForModel: boolean,
): HappyAgentWorkingPhase {
    if (waitingForModel) return "waiting";
    switch (session?.activity.kind) {
        case "thinking":
            return "thinking";
        case "generating_message":
            return "texting";
        case "generating_tool_call":
            return "generatingTools";
        case "executing_tool_call":
            return "callingTools";
        default:
            return "working";
    }
}

function workingLabelProject(
    session: SessionState | undefined,
    waitingForModel: boolean,
): string | undefined {
    if (waitingForModel) return undefined;
    const activity = session?.activity;
    if (activity === undefined || activity.kind === "idle") return undefined;
    const label = activity.label.split("\n")[0]?.trim() ?? "";
    if (label.length === 0) return undefined;
    return label.length > WORKING_LABEL_MAX
        ? `${label.slice(0, WORKING_LABEL_MAX - 1).trimEnd()}…`
        : label;
}

export interface HappyAgentWorkingWait {
    readonly startedAt: number;
    readonly dueAt: number;
}

function workingWaitProject(session: SessionState | undefined): HappyAgentWorkingWait | undefined {
    const wait = session?.activity.wait;
    if (wait === undefined || !Number.isFinite(wait.startedAt) || !Number.isFinite(wait.dueAt))
        return undefined;
    return { startedAt: wait.startedAt, dueAt: wait.dueAt };
}

function transcriptUsageProject(usage: SessionUsage): HappyAgentSessionUsage {
    return {
        currentProviderId: usage.currentProviderId,
        groups: usage.groups.map((group) => ({
            modelId: group.modelId,
            providerId: group.providerId,
            inputTokens: group.usage.input,
            outputTokens: group.usage.output,
            cacheReadTokens: group.usage.cacheRead,
            cacheWriteTokens: group.usage.cacheWrite,
            totalTokens: group.usage.totalTokens,
            ...(group.usage.reasoning === undefined
                ? {}
                : { reasoningTokens: group.usage.reasoning }),
            cost: group.usage.cost.total,
        })),
        totalTokens: usage.totalTokens,
        totalCost: usage.totalCost,
        ...(usage.context
            ? {
                  context: {
                      ...(usage.context.modelId === undefined
                          ? {}
                          : { modelId: usage.context.modelId }),
                      providerId: usage.context.providerId,
                      totalTokens: usage.context.totalTokens,
                      contextWindow: usage.context.contextWindow,
                      approximate: usage.context.approximate,
                  },
              }
            : {}),
        quotas: usage.quotas.map((quota) => ({
            providerId: quota.providerId,
            windows: (
                [
                    ["fiveHour", quota.quota.windows.fiveHour],
                    ["weekly", quota.quota.windows.weekly],
                ] as const
            ).flatMap(([kind, window]) =>
                window?.status === "available"
                    ? [{ kind, usedPercent: window.usedPercent, resetsAt: window.resetsAt }]
                    : [],
            ),
        })),
    };
}

function transcriptPendingUserInputsProject(
    session: SessionState,
): readonly HappyAgentUserInputRequest[] {
    return session.pendingUserInputs.map((request) => ({
        requestId: request.requestId,
        questions: request.questions.map((question) => ({
            id: question.id,
            header: question.header,
            question: question.question,
            multiSelect: question.multiSelect,
            required: question.required ?? false,
            options: question.options,
        })),
    }));
}

function transcriptQueuedMessagesProject(
    session: SessionState,
): readonly HappyAgentQueuedMessage[] {
    return session.pendingSteeringMessages.map((pending) => ({
        id: pending.message.id,
        text: pending.message.blocks
            .filter((block) => block.type === "text")
            .map((block) => block.text)
            .join("\n"),
    }));
}

function transcriptTasksProject(session: SessionState): readonly HappyAgentTodo[] {
    return session.tasks.map((task) => ({
        id: task.id,
        subject: task.subject,
        description: task.description,
        status: task.status,
        ...(task.activeForm === undefined ? {} : { activeForm: task.activeForm }),
        ...(task.owner === undefined ? {} : { owner: task.owner }),
        blockedBy: task.blockedBy,
        blocks: task.blocks,
    }));
}

function transcriptGoalProject(session: SessionState): HappyAgentGoal | undefined {
    const goal = session.goal;
    return goal === undefined
        ? undefined
        : {
              objective: goal.objective,
              status: goal.status,
              createdAt: goal.createdAt,
              updatedAt: goal.updatedAt,
          };
}

function transcriptSubagentsProject(session: SessionState): readonly SubagentSummary[] {
    return session.subagents.map((subagent) => ({
        id: subagent.id as HappyAgentSessionId,
        parentSessionId: subagent.parentSessionId as HappyAgentSessionId,
        ...(subagent.parentToolCallId === undefined
            ? {}
            : { parentToolCallId: subagent.parentToolCallId }),
        description: subagent.description,
        ...(subagent.taskName === undefined ? {} : { taskName: subagent.taskName }),
        modelId: subagent.modelId,
        status: subagent.status,
        depth: subagent.depth,
        createdAt: subagent.createdAt,
        updatedAt: subagent.updatedAt,
        ...(subagent.activeSince === undefined ? {} : { activeSince: subagent.activeSince }),
        ...(subagent.elapsedMs === undefined ? {} : { elapsedMs: subagent.elapsedMs }),
        ...(subagent.latestText === undefined ? {} : { latestText: subagent.latestText }),
        ...(subagent.totalTokens === undefined ? {} : { totalTokens: subagent.totalTokens }),
    }));
}

function transcriptBackgroundProcessesProject(
    session: SessionState,
): readonly HappyAgentBackgroundProcess[] {
    return session.backgroundProcesses.map((process) => ({
        id: process.sessionId,
        command: process.command,
        cwd: process.cwd,
        status: process.status,
    }));
}

function detachedProcessIdsFromElements(elements: readonly ChatElement[]): ReadonlySet<number> {
    const ids = new Set<number>();
    for (const element of elements) {
        if (element.kind !== "tool_call") continue;
        const presentation = element.presentation;
        if (presentation?.kind === "command" && presentation.terminalId !== undefined)
            ids.add(presentation.terminalId);
        if (presentation?.kind === "terminal_input") ids.add(presentation.terminalId);
    }
    return ids;
}

/** @internal Purely classifies the current process snapshot for activity UI. */
export function detachedProcessIdsUpdate(
    previous: ReadonlySet<number>,
    elements: readonly ChatElement[],
    processes: readonly SessionState["backgroundProcesses"][number][],
    activeTurn: SessionState["activeTurn"] = undefined,
): ReadonlySet<number> {
    const detachedIds = new Set(detachedProcessIdsFromElements(elements));
    const activeIds = new Set(processes.map((process) => process.sessionId));
    const next = new Set<number>();
    for (const id of previous) if (activeIds.has(id)) next.add(id);
    for (const id of detachedIds) if (activeIds.has(id)) next.add(id);
    if (activeTurn === undefined) for (const id of activeIds) next.add(id);
    if (next.size === previous.size && [...next].every((id) => previous.has(id))) return previous;
    return next;
}

function contextGaugeDerive(
    catalog: HappyAgentModelCatalog,
    context: HappyAgentSessionUsage["context"],
    selection?: { readonly modelId: string; readonly providerId: string },
): HappyAgentContextGauge | undefined {
    const catalogModel = (providerId: string, modelId: string) =>
        catalog.providers
            .find((provider) => provider.id === providerId)
            ?.models.find((model) => model.id === modelId);
    // The daemon compacts at the model's published threshold, so that point, not a share of
    // the window, is where the meter marks compaction; a limit at or past the window is no
    // threshold at all.
    const compactTokensOf = (
        model: HappyAgentModel | undefined,
        total: number,
    ): { readonly compactTokens: number } | Record<never, never> =>
        model?.autoCompactWindow !== undefined &&
        model.autoCompactWindow > 0 &&
        model.autoCompactWindow < total
            ? { compactTokens: model.autoCompactWindow }
            : {};
    if (!context) {
        if (selection === undefined) return undefined;
        const model = catalogModel(selection.providerId, selection.modelId);
        const total = model?.contextWindow;
        if (total === undefined || total <= 0) return undefined;
        return {
            usedTokens: 0,
            remainingTokens: total,
            totalTokens: total,
            remainingFraction: 1,
            ...compactTokensOf(model, total),
            approximate: false,
            measured: false,
        };
    }
    const model =
        context.modelId === undefined
            ? undefined
            : catalogModel(context.providerId, context.modelId);
    const total = context.contextWindow ?? model?.contextWindow;
    if (total == null || total <= 0) return undefined;
    const usedTokens = Math.max(0, Math.min(context.totalTokens, total));
    const remainingTokens = total - usedTokens;
    return {
        usedTokens,
        remainingTokens,
        totalTokens: total,
        remainingFraction: remainingTokens / total,
        ...compactTokensOf(model, total),
        approximate: context.approximate,
    };
}

interface HappyAgentImageRef {
    readonly messageId: string;
    readonly attachmentId: string;
}

interface HappyAgentGalleryImage extends HappyAgentImageRef {
    readonly attachment: ConversationAttachment;
}

function imageSourceOf(
    attachment: ConversationAttachment,
): { readonly url: string; readonly alt: string } | undefined {
    if (attachment.kind === "inlineImage")
        return {
            url: `data:${attachment.mediaType};base64,${attachment.data}`,
            alt: "Attached image",
        };
    if (attachment.attachmentKind === "image" && attachment.openUrl)
        return { url: attachment.openUrl, alt: attachment.name };
    return undefined;
}

function imageGalleryOf(entries: readonly ConversationEntry[]): readonly HappyAgentGalleryImage[] {
    const gallery: HappyAgentGalleryImage[] = [];
    for (const entry of entries) {
        if (entry.kind !== "message") continue;
        for (const attachment of entry.message.attachments)
            if (imageSourceOf(attachment))
                gallery.push({
                    messageId: entry.message.id,
                    attachmentId: attachment.id,
                    attachment,
                });
    }
    return gallery;
}

export interface HappyAgentOpenImage {
    readonly id: string;
    readonly url: string;
    readonly alt: string;
    readonly index: number;
    readonly total: number;
}

function openImageProject(
    entries: readonly ConversationEntry[],
    ref: HappyAgentImageRef | undefined,
): HappyAgentOpenImage | undefined {
    if (!ref) return undefined;
    const gallery = imageGalleryOf(entries);
    const index = gallery.findIndex(
        (image) => image.messageId === ref.messageId && image.attachmentId === ref.attachmentId,
    );
    const found = gallery[index];
    if (!found) return undefined;
    const source = imageSourceOf(found.attachment);
    return source === undefined
        ? undefined
        : {
              id: found.attachmentId,
              url: source.url,
              alt: source.alt,
              index,
              total: gallery.length,
          };
}

function sessionStatusProject(session: SessionState): HappyAgentSessionStatus {
    if (session.archived) return "archived";
    return session.status === "failed" ? "error" : session.status;
}

function sessionProject(session: SessionState): HappyAgentSession {
    const projectId = (session.projectId ??
        session.workspaceId ??
        session.sessionId) as HappyAgentProjectId;
    const scope =
        session.scope.kind === "workspace"
            ? {
                  kind: "workspace" as const,
                  projectId: session.scope.projectId as HappyAgentProjectId,
                  worktreeId: session.scope.workspaceId as HappyAgentWorktreeId,
              }
            : {
                  kind: "project" as const,
                  projectId:
                      session.scope.kind === "project"
                          ? (session.scope.projectId as HappyAgentProjectId)
                          : projectId,
              };
    return {
        id: session.sessionId as HappyAgentSessionId,
        scope,
        ...(session.orderKey === undefined ? {} : { orderKey: session.orderKey }),
        cwd: session.cwd,
        displayCwd: session.cwd,
        providerId: session.providerId,
        modelId: session.modelId,
        models: [],
        ...(session.effort === undefined
            ? {}
            : { effort: session.effort as HappyAgentThinkingLevel }),
        ...(session.serviceTier === undefined
            ? {}
            : { serviceTier: session.serviceTier as HappyAgentServiceTier }),
        permissionMode: session.permissionMode as HappyAgentPermissionMode,
        modelLocked: session.modelLocked,
        status: sessionStatusProject(session),
        ...(session.title === undefined ? {} : { title: session.title }),
        ...(session.recap === undefined ? {} : { recap: session.recap }),
        ...(session.draft === undefined ? {} : { draft: session.draft }),
        ...(session.draftUpdatedAt === undefined ? {} : { draftUpdatedAt: session.draftUpdatedAt }),
        queuedMessages: transcriptQueuedMessagesProject(session),
        pendingUserInputs: transcriptPendingUserInputsProject(session),
        ...(transcriptGoalProject(session) === undefined
            ? {}
            : { goal: transcriptGoalProject(session)! }),
        tasks: transcriptTasksProject(session),
        subagents: transcriptSubagentsProject(session),
        backgroundProcesses: transcriptBackgroundProcessesProject(session),
        createdAt: session.activity.since,
        updatedAt: session.activity.since,
    };
}

export interface HappyAgentChatSnapshot {
    readonly sessionId: HappyAgentSessionId;
    readonly ready: boolean;
    readonly archived: boolean;
    readonly title?: string;
    readonly cwd?: string;
    readonly draft?: string;
    readonly draftUpdatedAt?: number;
    readonly session: Loadable<HappyAgentSession>;
    readonly entries: readonly ConversationEntry[];
    readonly runStatus: "idle" | "running";
    readonly workingPhase: HappyAgentWorkingPhase;
    readonly workingLabel?: string;
    readonly workingWait?: HappyAgentWorkingWait;
    readonly activeTurnId?: string;
    readonly runId?: string;
    readonly runStartedAt?: number;
    readonly turnElapsedMs?: number;
    readonly transcriptComplete: boolean;
    readonly loadingMore: boolean;
    readonly loadMoreError?: string;
    readonly pendingUserInputs: readonly HappyAgentUserInputRequest[];
    readonly requestSubmissions: readonly ConversationRequestSubmission[];
    readonly requestSelections: ReadonlyMap<string, Readonly<Record<string, readonly string[]>>>;
    readonly queuedMessages: readonly HappyAgentQueuedMessage[];
    /** Complete ordered slash-command catalog projected from the focused agent. */
    readonly slashCommands: readonly HappyAgentSlashCommand[];
    readonly tasks: readonly HappyAgentTodo[];
    readonly goal?: HappyAgentGoal;
    readonly subagents: readonly SubagentSummary[];
    readonly backgroundProcesses: readonly HappyAgentBackgroundProcess[];
    readonly detachedBackgroundProcessIds: ReadonlySet<number>;
    readonly modelLocked: boolean;
    readonly showReasoning: boolean;
    readonly expandedTurnIds: ReadonlySet<string>;
    readonly usage?: HappyAgentSessionUsage;
    readonly usageLoading: boolean;
    readonly usageError?: string;
    readonly contextGauge?: HappyAgentContextGauge;
    readonly activityPanelOpen: boolean;
    readonly openImage?: HappyAgentOpenImage;
    readonly menus?: HappyAgentMenusSnapshot;
}

export type HappyAgentChatOutput =
    | {
          readonly type: "messageSent";
          readonly sessionId: HappyAgentSessionId;
          readonly steered: boolean;
      }
    | { readonly type: "runAborted"; readonly sessionId: HappyAgentSessionId }
    | {
          readonly type: "inputAnswered";
          readonly sessionId: HappyAgentSessionId;
          readonly requestId: string;
      };

export interface HappyAgentChatStore {
    get(): HappyAgentChatSnapshot;
    /** True while an action still needs this store to surface a rejection. */
    hasPendingMutations(): boolean;
    subscribe(listener: () => void): () => void;
    sessionRetry(): void;
    historyLoadMore(): void;
    messageSend(text: string, images?: readonly HappyAgentImageInput[]): Promise<void>;
    /** Exact-text human confirmation from voice. Never routes text into a pending question. */
    voiceMessageSendConfirmed(
        text: string,
        permissionMode: HappyAgentPermissionMode,
    ): Promise<void>;
    slashCommandInvoke(name: string, argumentsValue?: string): Promise<void>;
    draftSet(draft: string, updatedAt: number, origin: string): Promise<void>;
    runAbort(): Promise<void>;
    answerInput(input: HappyAgentUserInputAnswers): Promise<void>;
    requestSelectionUpdate(
        requestId: string,
        answers: Readonly<Record<string, readonly string[]>>,
    ): void;
    modelUpdate(input: HappyAgentModelSelection): void;
    effortUpdate(effort?: HappyAgentThinkingLevel): void;
    permissionModeUpdate(permissionMode: HappyAgentPermissionMode): void;
    serviceTierUpdate(serviceTier?: HappyAgentServiceTier): void;
    compact(): Promise<void>;
    backgroundProcessStop(processId: number): Promise<void>;
    usageGet(): Promise<HappyAgentSessionUsage>;
    activityPanelToggle(): void;
    activityPanelShow(): void;
    activityPanelClose(): void;
    imageOpen(messageId: string, attachmentId: string): void;
    imageNext(): void;
    imagePrevious(): void;
    imageClose(): void;
    reasoningToggle(): void;
    turnTraceToggle(turnId: string): void;
    [Symbol.dispose](): void;
}

export interface HappyAgentChatDeps {
    readonly catalog: HappyAgentModelCatalog;
    /**
     * Owner-only authoritative input: the connection's current model catalog.
     * The listener is called with it now and again on every change; the
     * returned function stops it, and the store calls it when disposed. The
     * pickers and context gauge re-derive from it; the session's own selection
     * is the daemon's and is left alone.
     */
    readonly catalogFollow?: (listener: (catalog: HappyAgentModelCatalog) => void) => () => void;
    readonly transcriptConnect: HappyAgentChatTranscriptConnect;
    readonly connectActions: Pick<
        HappyAgentConnection,
        | "answerUserInput"
        | "compactSession"
        | "invokeSlashCommand"
        | "sendMessage"
        | "sendMessageConfirmed"
        | "setDraft"
        | "setEffort"
        | "setPermissionMode"
        | "setServiceTier"
        | "stopBackgroundProcess"
        | "stopRun"
        | "switchModel"
    >;
    readonly connectMutationSubscribe: (
        listener: (rejection: MutationRejectedDelta) => void,
    ) => () => void;
    readonly selectionUsed?: (selection: HappyAgentSelection) => void;
    readonly modelSelect?: (
        current: HappyAgentSelection,
        input: HappyAgentModelSelection,
    ) => HappyAgentSelection;
    readonly output?: (event: HappyAgentChatOutput) => void;
    readonly effortRemembered?: HappyAgentModelEffortRemembered;
    /** Names the agents that send messages into this conversation. */
    readonly agentIdentities?: HappyAgentAgentIdentitySource;
}

export interface HappyAgentChatTranscriptConnection {
    close(): void;
    loadMore(token: string): void;
}

export type HappyAgentChatTranscriptConnect = (options: {
    readonly sessionId: HappyAgentSessionId;
    readonly onChange: (
        elements: readonly ChatElement[],
        session: SessionState,
        answeredUserInputs: readonly HappyAgentAnsweredUserInput[],
    ) => void;
    readonly onError: (error: unknown) => void;
}) => HappyAgentChatTranscriptConnection;

function transcriptSelectionOf(session: SessionState): HappyAgentSelection {
    return {
        providerId: session.providerId,
        modelId: session.modelId,
        effort: session.effort as HappyAgentThinkingLevel | undefined,
        permissionMode: session.permissionMode as HappyAgentPermissionMode,
        serviceTier: session.serviceTier as HappyAgentServiceTier | undefined,
    };
}

export function happyAgentChatStoreCreate(
    sessionId: HappyAgentSessionId,
    deps: HappyAgentChatDeps,
): HappyAgentChatStore {
    const output = deps.output ?? (() => undefined);
    const store = createStore<HappyAgentChatSnapshot>()(() => ({
        sessionId,
        session: { type: "loading" },
        modelLocked: false,
        ready: false,
        archived: false,
        entries: [],
        runStatus: "idle",
        workingPhase: "working",
        transcriptComplete: true,
        loadingMore: false,
        pendingUserInputs: [],
        requestSubmissions: [],
        requestSelections: new Map(),
        queuedMessages: [],
        slashCommands: [],
        tasks: [],
        subagents: [],
        backgroundProcesses: [],
        detachedBackgroundProcessIds: new Set<number>(),
        showReasoning: false,
        expandedTurnIds: new Set<string>(),
        usageLoading: false,
        activityPanelOpen: false,
    }));

    const listeners = new Set<() => void>();
    /* The connection's current model catalog; the daemon can change what it
       offers while this conversation is open. */
    let catalog = deps.catalog;
    let disposed = false;
    let active = false;
    let status: "loading" | "ready" | "error" = "loading";
    let error: UserError | undefined;
    let transcriptElements: readonly ChatElement[] | undefined;
    let transcriptSession: SessionState | undefined;
    let slashCommandSource: SessionState["slashCommands"] | undefined;
    let slashCommands: readonly HappyAgentSlashCommand[] = [];
    let transcriptAnsweredUserInputs: readonly HappyAgentAnsweredUserInput[] = [];
    let transcriptConnection: HappyAgentChatTranscriptConnection | undefined;
    let detachedBackgroundProcessIds: ReadonlySet<number> = new Set();
    let mutationRejection: MutationRejectedDelta | undefined;
    const pendingMutationIds = new Set<string>();
    const pendingMutationOrder: { readonly id: string; readonly trackedAt: number }[] = [];
    /* Replaced rather than edited, so the transcript projection can settle
       "were these the images the last projection saw?" by identity. */
    let sentImages: ReadonlyMap<string, readonly HappyAgentImageInput[]> = new Map();
    let sentImageBytes = 0;
    const conversationCache = happyAgentConversationCacheCreate();
    /* The agents that sent messages into this transcript, as the window knows
       them. One map is kept while none of them changed, because the projection
       compares it by identity and a new one rebuilds every turn. */
    let senderIdsFrom: readonly ChatElement[] | undefined;
    let senderIds: ReadonlySet<string> = new Set();
    let senders: ReadonlyMap<string, ConversationAgentIdentity> = new Map();
    let unsubscribeSenders: (() => void) | undefined;
    const sendersResolve = (): boolean => {
        const source = deps.agentIdentities;
        if (source === undefined || senderIds.size === 0) return false;
        const next = new Map<string, ConversationAgentIdentity>();
        for (const agentId of senderIds) {
            const known = source.lookup(agentId);
            if (known === undefined) source.request(agentId);
            else next.set(agentId, known);
        }
        if (
            next.size === senders.size &&
            [...next].every(([agentId, known]) => deepEqual(known, senders.get(agentId)))
        )
            return false;
        senders = next;
        return true;
    };
    const sendersFollow = (elements: readonly ChatElement[]): void => {
        if (elements === senderIdsFrom) return;
        senderIdsFrom = elements;
        const ids = happyAgentTranscriptSenderIds(elements);
        if (ids.size === senderIds.size && [...ids].every((agentId) => senderIds.has(agentId)))
            return;
        senderIds = ids;
        sendersResolve();
        // Followed only once someone has written in: a transcript nobody else
        // speaks in has nothing to name, and needs no word of the list moving.
        if (senderIds.size > 0 && deps.agentIdentities !== undefined)
            unsubscribeSenders ??= deps.agentIdentities.subscribe(() => {
                if (!disposed && sendersResolve()) commit();
            });
    };
    /* Nothing is projected into this conversation from outside it, and the
       projection compares what it was given last time, so the empty list is one
       object rather than a new one per commit. */
    const NO_EPHEMERAL: readonly ConversationEntry[] = [];
    let runStatus: "idle" | "running" = "idle";
    let runId: string | undefined;
    let runStartedAt: number | undefined;
    let turnElapsedMs: number | undefined;
    let showReasoning = false;
    let expandedTurnIds: ReadonlySet<string> = new Set();
    let activityPanelOpen = false;
    let openImageRef: HappyAgentImageRef | undefined;
    const requestSubmissions = new Map<string, ConversationRequestSubmission>();
    const requestMutationIds = new Map<string, string>();
    const requestSelections = new Map<string, Readonly<Record<string, readonly string[]>>>();

    const sessionLoadable = (): Loadable<HappyAgentSession> =>
        status === "ready" && transcriptSession !== undefined
            ? { type: "ready", value: sessionProject(transcriptSession) }
            : status === "error" && error !== undefined
              ? { type: "error", error }
              : { type: "loading" };

    const commit = (): void => {
        const previous = store.getState();
        const connected = transcriptSession;
        const elements = transcriptElements ?? [];
        const pendingUserInputs =
            connected === undefined ? [] : transcriptPendingUserInputsProject(connected);
        if (connected?.slashCommands !== slashCommandSource) {
            slashCommandSource = connected?.slashCommands;
            slashCommands = (connected?.slashCommands ?? []).map((command) => ({
                name: command.name,
                description: command.description,
                hasArguments: command.hasArguments,
                ...(command.kind === undefined ? {} : { kind: command.kind }),
            }));
        }
        const subagents = connected === undefined ? [] : transcriptSubagentsProject(connected);
        sendersFollow(elements);
        const tasks = connected === undefined ? [] : transcriptTasksProject(connected);
        const goal = connected === undefined ? undefined : transcriptGoalProject(connected);
        const backgroundProcesses =
            connected === undefined ? [] : transcriptBackgroundProcessesProject(connected);
        const built =
            connected === undefined
                ? []
                : happyAgentConversationProject({
                      cache: conversationCache,
                      elements,
                      sentImages,
                      sessionId,
                      showReasoning,
                      ephemeral: NO_EPHEMERAL,
                      pendingUserInputs,
                      answeredUserInputs: transcriptAnsweredUserInputs,
                      expandedGroupIds: expandedTurnIds,
                      subagents,
                      agentIdentities: senders,
                  });
        const withHistory: readonly ConversationEntry[] =
            connected?.loadingMore === true
                ? [
                      {
                          kind: "notice",
                          id: "happy-agent:loading-more",
                          variant: "notice",
                          level: "info",
                          text: "Loading earlier messages…",
                          sequence: "",
                      },
                      ...built,
                  ]
                : connected?.loadMoreError
                  ? [
                        {
                            kind: "notice",
                            id: "happy-agent:load-more-error",
                            variant: "notice",
                            level: "error",
                            title: "Earlier messages unavailable",
                            text: connected.loadMoreError,
                            sequence: "",
                        },
                        ...built,
                    ]
                  : built;
        const withMutation: readonly ConversationEntry[] =
            mutationRejection === undefined
                ? withHistory
                : [
                      {
                          kind: "notice",
                          id: `happy-agent:mutation-rejected:${mutationRejection.mutationId}`,
                          variant: "notice",
                          level: "error",
                          title: "Action not applied",
                          text: mutationRejection.message,
                          sequence: "",
                      },
                      ...withHistory,
                  ];
        const entries = entriesMerge(previous.entries, withMutation);
        const waitingForModel = waitingForModelProject(connected, transcriptElements, runStatus);
        const usage =
            connected?.usage === undefined ? undefined : transcriptUsageProject(connected.usage);
        const workingLabel = workingLabelProject(connected, waitingForModel);
        const workingWait = workingWaitProject(connected);
        const openImage = openImageProject(entries, openImageRef);
        const next: HappyAgentChatSnapshot = {
            sessionId,
            ready: connected !== undefined && connected.historyLoading !== true,
            archived: connected?.archived ?? false,
            ...(connected?.title === undefined ? {} : { title: connected.title }),
            ...(connected?.cwd === undefined ? {} : { cwd: connected.cwd }),
            ...(connected?.draft === undefined ? {} : { draft: connected.draft }),
            ...(connected?.draftUpdatedAt === undefined
                ? {}
                : { draftUpdatedAt: connected.draftUpdatedAt }),
            session: sessionLoadable(),
            entries,
            runStatus,
            workingPhase: workingPhaseProject(connected, waitingForModel),
            ...(workingLabel === undefined ? {} : { workingLabel }),
            ...(workingWait === undefined ? {} : { workingWait }),
            ...(runId === undefined ? {} : { runId }),
            ...(runStartedAt === undefined ? {} : { runStartedAt }),
            ...(turnElapsedMs === undefined ? {} : { turnElapsedMs }),
            transcriptComplete: connected?.transcriptComplete ?? true,
            loadingMore: connected?.loadingMore ?? false,
            ...(connected?.loadMoreError === undefined
                ? {}
                : { loadMoreError: connected.loadMoreError }),
            pendingUserInputs,
            requestSubmissions: [...requestSubmissions.values()],
            requestSelections: new Map(requestSelections),
            queuedMessages:
                connected === undefined ? [] : transcriptQueuedMessagesProject(connected),
            slashCommands,
            tasks,
            ...(goal === undefined ? {} : { goal }),
            subagents,
            backgroundProcesses,
            detachedBackgroundProcessIds,
            modelLocked: connected?.modelLocked ?? false,
            showReasoning,
            expandedTurnIds,
            ...(usage === undefined ? {} : { usage }),
            usageLoading: false,
            contextGauge: contextGaugeDerive(
                catalog,
                usage?.context,
                connected === undefined
                    ? undefined
                    : {
                          modelId: connected.modelId,
                          providerId: connected.providerId,
                      },
            ),
            activityPanelOpen,
            ...(openImage === undefined ? {} : { openImage }),
            ...(connected === undefined || connected.selectionKnown === false
                ? {}
                : {
                      menus: happyAgentMenusDerive(
                          catalog,
                          transcriptSelectionOf(connected),
                          deps.effortRemembered,
                      ),
                  }),
        };
        /* The transcript answers for itself: `entriesMerge` returns the very
           list it was given when nothing moved, so a new one is a change and
           needs no further inspection. Only when the transcript stood still is
           the rest of the snapshot worth comparing — and then the comparison
           settles the transcript on one reference rather than walking it. */
        if (entries !== previous.entries || !deepEqual(previous, next)) store.setState(next, true);
    };

    const start = (): void => {
        if (active || disposed) return;
        active = true;
        transcriptConnection = deps.transcriptConnect({
            sessionId,
            onChange: (elements, connected, answeredUserInputs) => {
                if (!active || disposed) return;
                transcriptElements = elements;
                transcriptSession = connected;
                transcriptAnsweredUserInputs = answeredUserInputs;
                // Only authoritative question state settles the local submission.
                // Keep selections through transport failure so Retry sends them again.
                const pendingRequests = new Set(
                    connected.pendingUserInputs.map((request) => request.requestId),
                );
                for (const requestId of requestSubmissions.keys()) {
                    if (pendingRequests.has(requestId)) continue;
                    requestSubmissions.delete(requestId);
                    requestSelections.delete(requestId);
                }
                for (const [mutationId, requestId] of requestMutationIds) {
                    if (pendingRequests.has(requestId)) continue;
                    requestMutationIds.delete(mutationId);
                    pendingMutationIds.delete(mutationId);
                }
                detachedBackgroundProcessIds = detachedProcessIdsUpdate(
                    detachedBackgroundProcessIds,
                    elements,
                    connected.backgroundProcesses,
                    connected.activeTurn,
                );
                runStatus = transcriptSessionBusy(connected) ? "running" : "idle";
                runId = connected.activeTurn?.runId;
                runStartedAt = connected.activeTurn?.startedAt;
                turnElapsedMs = undefined;
                if (connected.activeTurn === undefined)
                    for (let index = elements.length - 1; index >= 0; index -= 1) {
                        const element = elements[index];
                        if (element?.kind !== "group_end") continue;
                        turnElapsedMs = element.turnElapsedMs;
                        break;
                    }
                status = "ready";
                error = undefined;
                commit();
            },
            onError: (caught) => {
                if (!active || disposed) return;
                if (transcriptSession === undefined) {
                    status = "error";
                    error = happyAgentUserError(caught);
                } else {
                    transcriptSession = { ...transcriptSession, connection: "closed" };
                }
                commit();
            },
        });
    };

    const stop = (): void => {
        active = false;
        transcriptConnection?.close();
        transcriptConnection = undefined;
    };

    const notify = (): void => {
        for (const listener of listeners) listener();
    };
    const storeUnsubscribe = store.subscribe(notify);

    const connectMutationTrack = (mutationId: string): void => {
        const rejectionWasVisible = mutationRejection !== undefined;
        mutationRejection = undefined;
        pendingMutationIds.add(mutationId);
        pendingMutationOrder.push({ id: mutationId, trackedAt: Date.now() });
        while (pendingMutationOrder.length > PENDING_MUTATION_LIMIT) {
            const expired = pendingMutationOrder.shift();
            if (expired !== undefined) pendingMutationIds.delete(expired.id);
        }
        if (rejectionWasVisible) commit();
    };

    const pendingMutationActive = (): boolean => {
        const cutoff = Date.now() - PENDING_MUTATION_RETENTION_MS;
        while (pendingMutationOrder[0]?.trackedAt < cutoff) {
            const expired = pendingMutationOrder.shift();
            if (expired !== undefined) pendingMutationIds.delete(expired.id);
        }
        return pendingMutationIds.size > 0;
    };

    const unsubscribeCatalog = deps.catalogFollow?.((next) => {
        if (disposed || next === catalog) return;
        catalog = next;
        commit();
    });

    const unsubscribeMutationRejections = deps.connectMutationSubscribe((rejection) => {
        if (!pendingMutationIds.delete(rejection.mutationId)) return;
        const requestId = requestMutationIds.get(rejection.mutationId);
        if (requestId !== undefined) {
            requestMutationIds.delete(rejection.mutationId);
            requestSubmissions.set(requestId, {
                requestId,
                status: "failed",
                error: new UserError(rejection.message),
            });
            commit();
            return;
        }
        mutationRejection = rejection;
        commit();
    });

    const rejecting = async (run: () => void | Promise<void>): Promise<void> => {
        try {
            await run();
        } catch (caught) {
            throw happyAgentUserError(caught);
        }
    };

    const sentImagesRemember = (
        messageId: string,
        images: readonly HappyAgentImageInput[],
    ): void => {
        const bytes = images.reduce((total, image) => total + image.data.length, 0);
        const next = new Map(sentImages);
        next.set(messageId, images);
        sentImageBytes += bytes;
        for (const [oldest, held] of next) {
            if (sentImageBytes <= SENT_IMAGE_BUDGET_BYTES || oldest === messageId) break;
            next.delete(oldest);
            sentImageBytes -= held.reduce((total, image) => total + image.data.length, 0);
        }
        sentImages = next;
    };

    const answerInputRun = (input: HappyAgentUserInputAnswers): Promise<void> =>
        rejecting(() => {
            if (requestSubmissions.get(input.requestId)?.status === "pending") return;
            requestSubmissions.set(input.requestId, {
                requestId: input.requestId,
                status: "pending",
            });
            commit();
            try {
                const mutationId = deps.connectActions.answerUserInput(sessionId, input.requestId, {
                    answers: input.answers,
                });
                requestMutationIds.set(mutationId, input.requestId);
                connectMutationTrack(mutationId);
            } catch (error) {
                requestSubmissions.set(input.requestId, {
                    requestId: input.requestId,
                    status: "failed",
                    error: happyAgentUserError(error),
                });
                commit();
                throw error;
            }
            output({ type: "inputAnswered", sessionId, requestId: input.requestId });
        });

    const pendingQuestionAnswer = async (text: string): Promise<{ textUsed: boolean }> => {
        const request = store.getState().pendingUserInputs[0];
        const message = text.trim();
        if (
            request === undefined ||
            message.length === 0 ||
            requestSubmissions.get(request.requestId)?.status === "pending"
        )
            return { textUsed: false };
        const ticked = requestSelections.get(request.requestId) ?? {};
        const answers: Record<string, readonly string[]> = {};
        let textUsed = false;
        for (const question of request.questions) {
            const chosen = ticked[question.id] ?? [];
            if (chosen.length > 0) answers[question.id] = [...chosen];
            else {
                answers[question.id] = [message];
                textUsed = true;
            }
        }
        await answerInputRun({ requestId: request.requestId, answers });
        return { textUsed };
    };

    const imageStep = (direction: 1 | -1): void => {
        if (openImageRef === undefined) return;
        const gallery = imageGalleryOf(store.getState().entries);
        if (gallery.length < 2) return;
        const at = gallery.findIndex(
            (image) =>
                image.messageId === openImageRef?.messageId &&
                image.attachmentId === openImageRef.attachmentId,
        );
        if (at < 0) return;
        const next = gallery[(at + direction + gallery.length) % gallery.length];
        if (next === undefined) return;
        openImageRef = { messageId: next.messageId, attachmentId: next.attachmentId };
        commit();
    };

    return {
        get: () => store.getState(),
        hasPendingMutations: pendingMutationActive,
        subscribe(listener) {
            listeners.add(listener);
            if (listeners.size === 1) start();
            return () => {
                listeners.delete(listener);
                if (listeners.size === 0) stop();
            };
        },
        sessionRetry() {
            if (!active || status !== "error") return;
            stop();
            status = "loading";
            error = undefined;
            start();
            commit();
        },
        historyLoadMore() {
            const token = transcriptSession?.loadMoreToken;
            if (token === undefined || transcriptSession?.loadingMore === true) return;
            transcriptConnection?.loadMore(token);
        },
        voiceMessageSendConfirmed: (text, permissionMode) =>
            rejecting(async () => {
                const current = store.getState();
                if (current.session.type !== "ready")
                    throw new Error("The conversation is not ready.");
                if (
                    current.pendingUserInputs.length > 0 ||
                    current.session.value.pendingUserInputs.length > 0
                )
                    throw new Error(
                        "Answer the pending question yourself before sending a voice draft.",
                    );
                if (current.session.value.permissionMode !== permissionMode)
                    throw new Error("The access mode changed. Review the message again.");
                const steered = runStatus === "running";
                await deps.connectActions.sendMessageConfirmed(sessionId, text);
                output({ type: "messageSent", sessionId, steered });
            }),
        messageSend: (text, images) =>
            rejecting(async () => {
                if ((await pendingQuestionAnswer(text)).textUsed) return;
                const steered = runStatus === "running";
                const mutationId = deps.connectActions.sendMessage(
                    sessionId,
                    images && images.length > 0
                        ? {
                              text,
                              content: [
                                  { type: "text", text },
                                  ...images.map((image) => ({
                                      type: "image" as const,
                                      mediaType: image.mediaType,
                                      data: image.data,
                                  })),
                              ],
                          }
                        : text,
                );
                if (images && images.length > 0) sentImagesRemember(mutationId, images);
                connectMutationTrack(mutationId);
                output({ type: "messageSent", sessionId, steered });
            }),
        slashCommandInvoke: (name, argumentsValue) =>
            rejecting(() => {
                // A skill is not a command the daemon runs on its own: it is a
                // document the model has to read before it acts. So invoking one
                // sends an ordinary user message that carries an explicit request
                // for the `read_skill` tool. Happy Agent runs that tool before
                // inference, records the call and its result in the transcript, and
                // the model continues with the instructions loaded. The message text
                // is the command as the reader typed it, so the transcript shows the
                // invocation and the model reads the ask beside the loaded document.
                const command = slashCommands.find((one) => one.name === name);
                if (command?.kind === "skill") {
                    const steered = runStatus === "running";
                    const text =
                        argumentsValue === undefined || argumentsValue.trim().length === 0
                            ? `/${name}`
                            : `/${name} ${argumentsValue}`;
                    connectMutationTrack(
                        deps.connectActions.sendMessage(sessionId, {
                            text,
                            content: [
                                { type: "text", text },
                                {
                                    type: "tool_call_request",
                                    name: "read_skill",
                                    arguments: { name },
                                },
                            ],
                        }),
                    );
                    output({ type: "messageSent", sessionId, steered });
                    return;
                }
                connectMutationTrack(
                    deps.connectActions.invokeSlashCommand(sessionId, name, argumentsValue),
                );
            }),
        draftSet: (draft, updatedAt, origin) =>
            rejecting(() => {
                connectMutationTrack(
                    deps.connectActions.setDraft(sessionId, { draft, updatedAt, origin }),
                );
            }),
        runAbort: () =>
            rejecting(() => {
                connectMutationTrack(deps.connectActions.stopRun(sessionId));
                output({ type: "runAborted", sessionId });
            }),
        answerInput: answerInputRun,
        requestSelectionUpdate(requestId, answers) {
            requestSelections.set(requestId, answers);
            commit();
        },
        modelUpdate(input) {
            const connected = transcriptSession;
            if (connected === undefined) return;
            const current = transcriptSelectionOf(connected);
            const next =
                deps.modelSelect?.(current, input) ??
                happyAgentSelectionModelUpdate(catalog, current, input);
            deps.selectionUsed?.(next);
            connectMutationTrack(
                deps.connectActions.switchModel(sessionId, {
                    providerId: next.providerId,
                    modelId: next.modelId,
                }),
            );
            if (next.effort !== current.effort)
                connectMutationTrack(deps.connectActions.setEffort(sessionId, next.effort));
            if (next.serviceTier !== current.serviceTier)
                connectMutationTrack(
                    deps.connectActions.setServiceTier(sessionId, next.serviceTier),
                );
        },
        effortUpdate(effort) {
            if (transcriptSession !== undefined)
                deps.selectionUsed?.(
                    happyAgentSelectionEffortUpdate(
                        transcriptSelectionOf(transcriptSession),
                        effort,
                    ),
                );
            connectMutationTrack(deps.connectActions.setEffort(sessionId, effort));
        },
        permissionModeUpdate(permissionMode) {
            connectMutationTrack(deps.connectActions.setPermissionMode(sessionId, permissionMode));
        },
        serviceTierUpdate(serviceTier) {
            if (transcriptSession !== undefined)
                deps.selectionUsed?.(
                    happyAgentSelectionServiceTierUpdate(
                        transcriptSelectionOf(transcriptSession),
                        serviceTier,
                    ),
                );
            connectMutationTrack(deps.connectActions.setServiceTier(sessionId, serviceTier));
        },
        compact: () =>
            rejecting(() => {
                connectMutationTrack(deps.connectActions.compactSession(sessionId));
            }),
        backgroundProcessStop: (processId) =>
            rejecting(() => {
                connectMutationTrack(
                    deps.connectActions.stopBackgroundProcess(sessionId, processId),
                );
            }),
        usageGet() {
            const usage = transcriptSession?.usage;
            return usage === undefined
                ? Promise.reject(new UserError("Usage is not available yet."))
                : Promise.resolve(transcriptUsageProject(usage));
        },
        activityPanelToggle() {
            activityPanelOpen = !activityPanelOpen;
            commit();
        },
        activityPanelShow() {
            if (activityPanelOpen) return;
            activityPanelOpen = true;
            commit();
        },
        activityPanelClose() {
            if (!activityPanelOpen) return;
            activityPanelOpen = false;
            commit();
        },
        imageOpen(messageId, attachmentId) {
            const ref = { messageId, attachmentId };
            if (openImageProject(store.getState().entries, ref) === undefined) return;
            openImageRef = ref;
            commit();
        },
        imageNext() {
            imageStep(1);
        },
        imagePrevious() {
            imageStep(-1);
        },
        imageClose() {
            if (openImageRef === undefined) return;
            openImageRef = undefined;
            commit();
        },
        reasoningToggle() {
            showReasoning = !showReasoning;
            commit();
        },
        turnTraceToggle(turnId) {
            const next = new Set(expandedTurnIds);
            if (!next.delete(turnId)) next.add(turnId);
            expandedTurnIds = next;
            commit();
        },
        [Symbol.dispose]() {
            if (disposed) return;
            disposed = true;
            stop();
            unsubscribeMutationRejections();
            unsubscribeCatalog?.();
            unsubscribeSenders?.();
            storeUnsubscribe();
            listeners.clear();
            pendingMutationIds.clear();
            pendingMutationOrder.length = 0;
            sentImages = new Map();
            sentImageBytes = 0;
            conversationCache.context = undefined;
            conversationCache.elements = undefined;
            conversationCache.entries = undefined;
            conversationCache.groups = new Map();
            requestSubmissions.clear();
            requestMutationIds.clear();
            requestSelections.clear();
        },
    };
}

packages/happy-desktop-ui/src/AgentActiv.oldContent:
import { useState, type CSSProperties } from "react";
import type {
    ConversationActivity,
    ConversationActivityPresentation,
    ConversationActivityReview,
    ConversationActivityStatus,
    ConversationFileDiff,
    ConversationJson,
    ConversationToolCall,
} from "happy-desktop-state";
import { compactCount, changeCountLabel } from "./countText";
import { CopyButton } from "./CopyButton";
import { DiffSnippet, type DiffLine } from "./DiffSnippet";
import { filePreviewKind } from "./FilePreview";
import { Icon, type IconName } from "./Icon";
import { useMessageListDisclosureAnchor } from "./messageListDisclosureAnchor";
import { renderMessageMarkdown } from "./MessageMarkdown";
import { ScrollingText } from "./ScrollingText";
import { Spinner } from "./Spinner";
import { TypedText } from "./TypedText";
import { Ionicon, Octicon } from "./vectorIcons/VectorIcon";

/**
 * Which live labels type when their value changes. This affects animation
 * only: wording, timestamps, controls, and every other piece of row content
 * stay identical across profiles.
 */
export type ActivityMotion = "typewriter" | "verb-typed" | "calm-typed" | "calm";

/**
 * Content treatment independent of animation. `focused` keeps one action word
 * for the call's life, leaves copy metadata to the detail surface, and reveals
 * the tool's start time over the row's trailing edge.
 */
export type ActivityTreatment = "detailed" | "focused";

export type AgentActivityRowProps = {
    activity: ConversationActivity;
    /** Motion profile for live updates. Defaults to the historical `typewriter`. */
    motion?: ActivityMotion;
    /** Row content/chrome policy, independent of which labels animate. */
    treatment?: ActivityTreatment;
    /** Opens a tool's complete body in an owner-provided detail surface. */
    onToolSelect?: (tool: ConversationToolCall) => void;
    /**
     * Opens the workspace file a tool call worked on, in the product's file
     * viewer. A row whose tool names no single showable file offers nothing,
     * and a surface with no workspace behind it passes nothing.
     */
    onFileOpen?: (path: string) => void;
    /** Start expanded (blueprint/tests). Otherwise rich bodies collapse by default. */
    defaultExpanded?: boolean;
    /** Controlled disclosure state for a virtualized transcript row. */
    expanded?: boolean;
    /** Reports disclosure changes so an owner can rebuild modeled row geometry. */
    onExpandedChange?: (expanded: boolean) => void;
    /**
     * Local conversation tool rows: one neutral line aligned with agent text, with
     * no inline result or expand affordance.
     */
    singleLine?: boolean;
    /** Durable event time, revealed with the row's trailing hover metadata. */
    time?: string;
    className?: string;
    "data-testid"?: string;
    style?: CSSProperties;
};

/** Max file diffs rendered per tool before an overflow note replaces the rest. */
const MAX_DIFF_FILES = 5;
/** Head/tail line budget for exec-command output before the middle is elided. */
const EXEC_HEAD_TAIL = 5;
/** Bounded JSON budget for generic tool-call arguments (chars). */
const JSON_BUDGET = 4096;
/** MCP result-row budget: dim child rows shown before an overflow note (A3). */
const MCP_RESULT_ROWS = 5;

function useExpansion(
    defaultExpanded: boolean,
    expanded: boolean | undefined,
    onExpandedChange: ((expanded: boolean) => void) | undefined,
) {
    const [ownExpanded, setOwnExpanded] = useState(defaultExpanded);
    const value = expanded ?? ownExpanded;
    return [
        value,
        (next: boolean) => {
            if (expanded === undefined) setOwnExpanded(next);
            onExpandedChange?.(next);
        },
    ] as const;
}

function AgentActivityTime(props: { time?: string }) {
    return props.time ? (
        <span className="happy-agent-activity__time" data-happy-desktop-ui="agent-activity-time">
            {props.time}
        </span>
    ) : null;
}

/**
 * Parses an MCP tool name (`mcp__server__tool`) into its server and tool parts.
 * Returns undefined for any name that is not an MCP invocation, so the caller
 * falls back to the generic tool rendering path.
 */
function parseMcpToolName(name: string): { server: string; tool: string } | undefined {
    if (!name.startsWith("mcp__")) return undefined;
    const parts = name.split("__");
    if (parts.length < 3) return undefined;
    return { server: parts[1]!, tool: parts.slice(2).join(" ") };
}

/** Splits an MCP result into ≤`budget` dim rows, returning the overflow count. */
function mcpResultRows(display: string, budget: number): { rows: string[]; omitted: number } {
    const all = display.replace(/\n+$/, "").split("\n");
    if (all.length <= budget) return { rows: all, omitted: 0 };
    return { rows: all.slice(0, budget), omitted: all.length - budget };
}

/** Friendly tool label — mirrors the TUI `humanizeToolName` mapping (A3). */
function humanizeToolName(name: string): string {
    const explicit: Record<string, string> = {
        Agent: "Subagent",
        compact: "Context compaction",
        TaskInput: "Terminal input",
        TaskList: "Task list",
        TaskOutput: "Background output",
        spawn_agent: "Start subagent",
        wait_agent: "Wait for subagents",
        workflow: "Workflow",
        write_stdin: "Terminal input",
    };
    if (explicit[name]) return explicit[name]!;
    if (name.startsWith("mcp__")) {
        const parts = name.split("__");
        if (parts.length >= 3) return `${parts[1]} · ${parts.slice(2).join(" ")}`;
    }
    return name
        .replace(/[_-]+/g, " ")
        .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
        .replace(/\s+/g, " ")
        .trim()
        .replace(/^./, (character) => character.toUpperCase());
}

/**
 * Tools that type into a terminal that is already running, rather than starting
 * one. Matched by name for the window before the result arrives, when the row
 * has no presentation to classify it by.
 */
const TERMINAL_INPUT_TOOL = /stdin|terminal_?input|taskinput/;

/** Active/done verb for a tool by name + status (A2/A3). */
function toolVerb(
    name: string,
    status: ConversationActivityStatus,
    presentation?: ConversationActivityPresentation,
): string {
    if (presentation?.type === "agentSpawn") {
        if (status === "awaitingApproval") return "Awaiting approval to spawn";
        if (status === "failed") return "Failed to spawn";
        if (status === "stopped") return "Stopped spawning";
        return status === "running" ? "Spawning" : "Spawned";
    }
    if (status === "awaitingApproval") return "Awaiting approval";
    if (status === "stopped") return "Stopped";
    const active = status === "running";
    const lower = name.toLowerCase();
    if (presentation?.type === "compaction") {
        return status === "failed" ? "Failed" : active ? "Compacting" : "Compacted";
    }
    if (presentation?.type === "search") return active ? "Searching" : "Searched";
    if (presentation?.type === "exploration") return active ? "Exploring" : "Explored";
    // Typing into a terminal that is already running is not the same act as
    // starting one, and it is certainly not editing a file: `write_stdin` would
    // otherwise fall through to the write/edit family below and claim to have
    // edited something called "Write stdin".
    if (presentation?.type === "backgroundTerminalInteraction" || TERMINAL_INPUT_TOOL.test(lower))
        return active ? "Typing" : "Typed";
    // Waiting ends when a child sends input. That expected wake-up is projected
    // as success; the verb describes the wait rather than a generic tool use.
    if (lower === "wait_agent") return active ? "Waiting" : "Waited";
    if (presentation?.type === "execCommand" || /(bash|exec|shell|command|run)/.test(lower))
        return lower === "powershell" ? "PowerShell" : lower === "bash" ? "Bash" : "Shell";
    if (/(grep|find|glob|^ls$|list|search)/.test(lower)) return active ? "Exploring" : "Explored";
    if (/(read|view|cat|open)/.test(lower)) return active ? "Reading" : "Read";
    if (/(write|edit|patch|update|apply)/.test(lower)) return active ? "Editing" : "Edited";
    return active ? "Tool" : "Used";
}

/** Turns the lifecycle word into the stable action label used by focused rows. */
function toolVerbFocused(verb: string): string {
    switch (verb) {
        case "Exploring":
        case "Explored":
            return "Explore";
        case "Typing":
        case "Typed":
            return "Type";
        case "Reading":
            return "Read";
        case "Editing":
        case "Edited":
            return "Edit";
        case "Waiting":
        case "Waited":
            return "Wait";
        case "Used":
            return "Tool";
        default:
            return verb;
    }
}

/**
 * Tool → the glyph saying what kind of work it was. Commands use Octicons
 * `code`, failed tools use Octicons `alert`, and file edits use Ionicons
 * `document-outline`; the remaining tool families use the curated vocabulary.
 */
type ToolGlyph =
    | { set: "house"; name: IconName }
    | { set: "ionicons"; name: "document-outline" | "terminal-outline" }
    | { set: "octicons"; name: "alert" | "code" };

function toolGlyph(
    name: string,
    presentation: ConversationActivityPresentation | undefined,
    failed: boolean,
): ToolGlyph {
    if (failed) return { set: "octicons", name: "alert" };
    if (presentation?.type === "agentSpawn") return { set: "house", name: "agents" };
    if (presentation?.type === "compaction") return { set: "house", name: "filter" };
    if (presentation?.type === "search") return { set: "house", name: "globe" };
    if (presentation?.type === "exploration") return { set: "house", name: "search" };
    if (presentation?.type === "fileDiff") return { set: "ionicons", name: "document-outline" };
    const lower = name.toLowerCase();
    // Typing into a running terminal gets the terminal itself, so it is not
    // mistaken for the command that started one or for a file edit.
    if (presentation?.type === "backgroundTerminalInteraction" || TERMINAL_INPUT_TOOL.test(lower))
        return { set: "ionicons", name: "terminal-outline" };
    if (presentation?.type === "execCommand") return { set: "octicons", name: "code" };
    if (/(bash|exec|shell|command|run)/.test(lower)) return { set: "octicons", name: "code" };
    if (/(grep|find|glob|^ls$|list|search)/.test(lower)) return { set: "house", name: "search" };
    if (/(read|view|cat|open)/.test(lower)) return { set: "house", name: "doc" };
    if (/(write|edit|patch|update|apply)/.test(lower))
        return { set: "ionicons", name: "document-outline" };
    if (/(fetch|http|web|url|browser)/.test(lower)) return { set: "house", name: "globe" };
    if (/(task|todo|plan)/.test(lower)) return { set: "house", name: "tasks" };
    if (/(agent|spawn|subagent|workflow)/.test(lower)) return { set: "house", name: "agents" };
    return { set: "house", name: "zap" };
}

function ToolIcon(props: { glyph: ToolGlyph }) {
    if (props.glyph.set === "ionicons") return <Ionicon name={props.glyph.name} size={12} />;
    if (props.glyph.set === "octicons") return <Octicon name={props.glyph.name} size={12} />;
    return <Icon name={props.glyph.name} size={12} />;
}

/**
 * Retypes a tool label whenever this row's projected text changes.
 *
 * `typeFirst` also types the text the label opens with. A subject only retypes
 * when it changes, and whether a command ever changes is decided by the wire —
 * arguments that streamed in arrive as several values and type, the same
 * command delivered whole arrives once and does not. Rows that are live when
 * they appear ask for the first value to type too, so the same act looks the
 * same either way.
 */
function AgentActivityChangingText(props: { value: string; typed?: boolean; typeFirst?: boolean }) {
    return (props.typed ?? true) ? (
        <TypedText
            data-happy-desktop-ui="agent-activity-changing-text"
            {...(props.typeFirst ? { typeInitial: true } : {})}
            value={props.value}
        />
    ) : (
        <span
            className="happy-agent-activity__still-text"
            data-happy-desktop-ui="agent-activity-changing-text"
        >
            {props.value}
        </span>
    );
}

function explorationSummary(
    presentation: Extract<ConversationActivityPresentation, { type: "exploration" }>,
): string {
    const operations = presentation.operations;
    if (operations.every((operation) => operation.kind === "read")) {
        return [
            ...new Set(
                operations.flatMap((operation) =>
                    operation.kind === "read" ? [operation.name] : [],
                ),
            ),
        ].join(", ");
    }
    return operations
        .map((operation) => {
            if (operation.kind === "list") return `List ${operation.target}`;
            if (operation.kind === "read") return `Read ${operation.name}`;
            const detail =
                operation.query !== undefined && operation.path !== undefined
                    ? `${operation.query} in ${operation.path}`
                    : (operation.query ?? operation.path ?? operation.command);
            return `Search ${detail}`;
        })
        .join(" · ");
}

function compactionSummary(
    presentation: Extract<ConversationActivityPresentation, { type: "compaction" }>,
): string {
    const before = presentation.tokensBefore;
    const after = presentation.tokensAfter;
    if (before === undefined) {
        return after === undefined ? "context" : `context to ${contextTokenCount(after)} tokens`;
    }
    return after === undefined
        ? `context from ${contextTokenCount(before)} tokens`
        : `context ${contextTokenCount(before)} → ${contextTokenCount(after)} tokens`;
}

/** Context occupancy keeps one useful decimal deeper into the thousands than a file count. */
function contextTokenCount(tokens: number): string {
    if (tokens < 1_000) return String(Math.max(0, Math.round(tokens)));
    const thousands = tokens / 1_000;
    return `${thousands < 100 ? thousands.toFixed(1).replace(/\.0$/, "") : String(Math.round(thousands))}k`;
}

/** Status → semantic dot tone: warning while active/awaiting, error on stop/fail. */
function statusTone(status: ConversationActivityStatus): "success" | "warning" | "error" {
    if (status === "success") return "success";
    if (status === "failed" || status === "stopped") return "error";
    return "warning";
}

function diffVerb(kind: ConversationFileDiff["kind"]): string {
    if (kind === "add") return "Added";
    if (kind === "delete") return "Deleted";
    return "Edit";
}

/**
 * What was typed into a terminal, on one line. Terminal input is mostly control
 * characters and newlines, which paint as nothing at all: an interrupt would
 * otherwise be an empty row. Control codes are shown the way a terminal echoes
 * them, and a multi-line paste keeps its first line with the rest counted.
 */
function terminalInputSummary(input: string): string {
    const visible = input
        .replaceAll("\r\n", "\n")
        .replace(/\n+$/, "")
        // eslint-disable-next-line no-control-regex -- Terminal input is exactly where control codes arrive, and they must be made visible rather than filtered out.
        .replaceAll(/[\u0000-\u001F\u007F]/g, (character) =>
            character === "\n"
                ? "\n"
                : `^${String.fromCharCode(character.charCodeAt(0) ^ 0x40).toUpperCase()}`,
        );
    if (visible.length === 0) return "";
    const lines = visible.split("\n");
    return lines.length > 1 ? `${lines[0]!} … +${String(lines.length - 1)} lines` : lines[0]!;
}

function fileName(path: string): string {
    const normalized = path.replaceAll("\\", "/");
    return normalized.slice(normalized.lastIndexOf("/") + 1) || path;
}

/** Argument names the file-reading and file-writing tools carry a path under. */
const FILE_PATH_ARGUMENTS = ["file_path", "filePath", "path", "notebook_path"] as const;

/**
 * The one workspace file a tool call is about, when it is about exactly one and
 * Happy can show it. A multi-file edit has no single answer, and a tool whose
 * subject is an archive or a binary would only open on "no preview", so both
 * report nothing rather than offering a click that goes nowhere.
 */
function toolFilePath(tool: ConversationToolCall): string | undefined {
    const presentation = tool.presentation;
    const candidate =
        presentation?.type === "fileDiff"
            ? presentation.files.length === 1
                ? presentation.files[0]!.path
                : undefined
            : argumentFilePath(tool.arguments);
    if (candidate === undefined || candidate.trim().length === 0) return undefined;
    return filePreviewKind(candidate) === "binary" ? undefined : candidate;
}

function argumentFilePath(argumentsValue: ConversationToolCall["arguments"]): string | undefined {
    if (typeof argumentsValue !== "object" || argumentsValue === null) return undefined;
    if (Array.isArray(argumentsValue)) return undefined;
    for (const key of FILE_PATH_ARGUMENTS) {
        const value = (argumentsValue as Record<string, ConversationJson>)[key];
        if (typeof value === "string" && value.trim().length > 0) return value;
    }
    return undefined;
}

function diffCounts(file: ConversationFileDiff): { added: number; deleted: number } {
    if (file.added !== undefined || file.deleted !== undefined)
        return { added: file.added ?? 0, deleted: file.deleted ?? 0 };
    let added = 0;
    let deleted = 0;
    for (const hunk of file.hunks)
        for (const line of hunk.lines) {
            if (line.kind === "add") added += 1;
            else if (line.kind === "delete") deleted += 1;
        }
    return { added, deleted };
}

/** Flattens a file's hunks into numbered DiffSnippet lines with `@@` meta rows. */
function diffLines(file: ConversationFileDiff): DiffLine[] {
    const lines: DiffLine[] = [];
    file.hunks.forEach((hunk, index) => {
        if (file.hunks.length > 1 || index > 0)
            lines.push({
                kind: "meta",
                text: `@@ -${hunk.oldStart} +${hunk.newStart} @@`,
            });
        let oldLine = hunk.oldStart;
        let newLine = hunk.newStart;
        for (const line of hunk.lines) {
            if (line.kind === "add") {
                lines.push({ kind: "add", number: newLine, text: line.text });
                newLine += 1;
            } else if (line.kind === "delete") {
                lines.push({ kind: "del", number: oldLine, text: line.text });
                oldLine += 1;
            } else {
                lines.push({ kind: "context", number: newLine, text: line.text });
                oldLine += 1;
                newLine += 1;
            }
        }
    });
    return lines;
}

/** Keep the first and last `budget` lines, eliding the middle with a count note. */
function headTail(text: string, budget: number): { lines: string[]; omitted: number } {
    const all = text.replace(/\n+$/, "").split("\n");
    if (all.length <= budget * 2) return { lines: all, omitted: 0 };
    return {
        lines: [...all.slice(0, budget), ...all.slice(all.length - budget)],
        omitted: all.length - budget * 2,
    };
}

/**
 * Whether a tool's arguments have anything to show, answered without
 * serializing them. A call still being generated grows its arguments with every
 * frame of the stream, and the row only asks this to decide whether it can be
 * opened at all — so the question is settled from the shape rather than from a
 * string the row is about to throw away.
 */
function jsonPresent(value: ConversationJson): boolean {
    if (value === null) return false;
    if (Array.isArray(value)) return value.length > 0;
    if (typeof value === "object") return Object.keys(value).length > 0;
    return true;
}

function boundedJson(value: ConversationJson): string | undefined {
    if (!jsonPresent(value)) return undefined;
    const text = JSON.stringify(value, null, 2);
    return text.length > JSON_BUDGET ? `${text.slice(0, JSON_BUDGET)}\n… truncated` : text;
}

function ChildRow(props: { tone?: "muted" | "error"; children: React.ReactNode }) {
    return (
        <div
            className="happy-agent-activity__child"
            data-tone={props.tone ?? "muted"}
            data-happy-desktop-ui="agent-activity-child"
        >
            <span aria-hidden="true" className="happy-agent-activity__child-marker">
                └
            </span>
            <span
                className="happy-agent-activity__child-text"
                data-happy-desktop-ui="agent-activity-child-text"
            >
                {props.children}
            </span>
        </div>
    );
}

function PermissionReviewRow(props: { review: ConversationActivityReview }) {
    const { review } = props;
    const title =
        review.decision === "allow"
            ? "Approved"
            : review.decision === "deny"
              ? "Denied"
              : "Awaiting approval";
    return (
        <div className="happy-agent-activity__review" data-happy-desktop-ui="agent-activity-review">
            <span aria-hidden="true" className="happy-agent-activity__child-marker">
                └
            </span>
            <span className="happy-agent-activity__review-body">
                <span
                    className="happy-agent-activity__review-title"
                    data-happy-desktop-ui="agent-activity-review-title"
                >
                    {title} · {review.action}
                </span>
                <span className="happy-agent-activity__review-reason">{review.reason}</span>
                <span
                    className="happy-agent-activity__review-risk"
                    data-risk={review.risk}
                    data-happy-desktop-ui="agent-activity-review-risk"
                >
                    Risk: {review.risk}
                </span>
            </span>
        </div>
    );
}

/**
 * One tool invocation: a rich body chosen by `presentation` (file diff, exec
 * command, background-terminal interaction) with a generic header + result/args
 * fallback. A colored status dot and verb encode running/awaiting-approval/
 * success/failed/stopped, and a pending `review` renders an inline "Awaiting
 * approval" child line. Collapse/expand of the rich body is the only local UI
 * state; every value comes from props.
 */
function AgentToolActivity(props: {
    tool: ConversationToolCall;
    defaultExpanded?: boolean;
    expanded?: boolean;
    onExpandedChange?: (expanded: boolean) => void;
    motion?: ActivityMotion;
    treatment?: ActivityTreatment;
    onSelect?: (tool: ConversationToolCall) => void;
    onFileOpen?: (path: string) => void;
    singleLine?: boolean;
    time?: string;
}) {
    const { tool } = props;
    const presentation = tool.presentation;
    const [expanded, setExpanded] = useExpansion(
        props.defaultExpanded ?? false,
        props.expanded,
        props.onExpandedChange,
    );
    const singleLine = props.singleLine ?? false;
    const running = tool.status === "running";
    const motion = props.motion ?? "typewriter";
    const focused = props.treatment === "focused";
    const verbTyped = motion === "typewriter" || motion === "verb-typed";
    /** The subject types only in the profiles that type it. */
    const subjectTyped = motion === "typewriter" || motion === "calm-typed";

    const tone = singleLine ? "neutral" : statusTone(tool.status);

    // MCP tool calls (`mcp__server__tool`) have no protocol presentation; the TUI
    // derives their block at render time from the name, arguments, and result. We
    // do the same, but only when no richer presentation (diff/exec) applies.
    const mcp = presentation ? undefined : parseMcpToolName(tool.toolName);

    let primaryText: string;
    let stats: { added: number; deleted: number } | undefined;
    let verb: string;
    if (mcp) {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = `${mcp.server} · ${mcp.tool}`;
    } else if (presentation?.type === "agentSpawn") {
        verb = toolVerb(tool.toolName, tool.failed ? "failed" : tool.status, presentation);
        primaryText = presentation.model ? `${presentation.model.name} sub-agent` : "sub-agent";
    } else if (presentation?.type === "compaction") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = compactionSummary(presentation);
    } else if (presentation?.type === "search") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = presentation.query;
    } else if (presentation?.type === "exploration") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = explorationSummary(presentation);
    } else if (presentation?.type === "fileDiff") {
        const first = presentation.files[0];
        verb = first ? diffVerb(first.kind) : toolVerb(tool.toolName, tool.status, presentation);
        primaryText = first ? fileName(first.path) : humanizeToolName(tool.toolName);
        stats = presentation.files.reduce(
            (total, file) => {
                const counts = diffCounts(file);
                return {
                    added: total.added + counts.added,
                    deleted: total.deleted + counts.deleted,
                };
            },
            { added: 0, deleted: 0 },
        );
    } else if (presentation?.type === "execCommand") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = presentation.command;
    } else if (presentation?.type === "backgroundTerminalInteraction") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        // What was typed, not the command that started the terminal: several
        // interactions with one background task all carry the same command, so
        // showing that made a run of rows read as the same thing happening over
        // and over. The command is context, and it moves into the body below.
        primaryText = terminalInputSummary(presentation.input) || presentation.command;
    } else {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText =
            tool.toolName.toLowerCase() === "wait_agent"
                ? "for subagents"
                : humanizeToolName(tool.toolName);
    }
    if (focused && presentation?.type !== "fileDiff") verb = toolVerbFocused(verb);
    /* Ran outside the sandbox. Said in colour alone — the whole line turns
       amber — because a word in the verb would push the command itself out of
       a row that is already short. A call that stopped or failed never got
       that far, and its own status is the louder fact. */
    const elevated =
        tool.elevated === true &&
        tool.status !== "stopped" &&
        tool.status !== "failed" &&
        !tool.failed;
    const filePath = props.onFileOpen ? toolFilePath(tool) : undefined;

    /* Only a row that is open, and open on its arguments, ever prints them.
       Serializing them anyway cost the whole argument tree on every frame of a
       call still being generated — for a transcript row that never shows a body
       at all, and for a closed row nobody has asked to see. */
    const argsPresent = presentation === undefined && jsonPresent(tool.arguments);
    const execOutput =
        presentation?.type === "execCommand"
            ? headTail(presentation.output, EXEC_HEAD_TAIL)
            : undefined;
    const terminalInput =
        presentation?.type === "backgroundTerminalInteraction"
            ? presentation.input.replace(/\n+$/, "").split("\n")
            : undefined;
    const compactionFailure =
        presentation?.type === "compaction" ? presentation.failureReason : undefined;

    /* What a reader reaches for the clipboard to get: the subject that scrolled
       out of the row, followed by the output or result the row only shows in
       part. Both are elided on screen, so the copy is the unabridged text. */
    const copyText = [
        primaryText,
        presentation?.type === "execCommand"
            ? presentation.output
            : presentation?.type === "search"
              ? presentation.sources?.map((source) => `${source.title}\n${source.url}`).join("\n")
              : presentation?.type === "compaction"
                ? presentation.failureReason
                : presentation === undefined
                  ? tool.display
                  : undefined,
    ]
        .map((part) => part?.replace(/\n+$/, ""))
        .filter((part): part is string => part !== undefined && part.length > 0)
        .join("\n");

    const hasBody = singleLine
        ? false
        : presentation?.type === "fileDiff"
          ? presentation.files.length > 0
          : presentation?.type === "search"
            ? (presentation.sources?.length ?? 0) > 0
            : presentation?.type === "execCommand"
              ? presentation.output.trim().length > 0
              : presentation?.type === "backgroundTerminalInteraction"
                ? presentation.input.trim().length > 0
                : argsPresent;

    // MCP results render as capped dim rows (≤5, then "… N more"); an interrupted
    // call collapses to a single "Interrupted." row, matching the TUI.
    const mcpResult = mcp
        ? tool.failure?.kind === "interrupted"
            ? { rows: ["Interrupted."], omitted: 0 }
            : tool.display && tool.display.trim().length > 0
              ? mcpResultRows(tool.display, MCP_RESULT_ROWS)
              : { rows: ["(empty result)"], omitted: 0 }
        : undefined;

    const genericResult =
        mcp || presentation
            ? undefined
            : tool.display !== undefined && tool.display.length > 0
              ? tool.display
              : "(empty result)";

    const header = (
        <>
            {singleLine ? null : (
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__dot"
                    data-tone={tone}
                    data-happy-desktop-ui="agent-activity-dot"
                />
            )}
            {/* What kind of work this was, told at a glance. It is decoration
                over the verb beside it, which already says the same thing in
                words, so it stays out of the accessibility tree. */}
            <span
                aria-hidden="true"
                className="happy-agent-activity__glyph"
                data-happy-desktop-ui="agent-activity-glyph"
            >
                {running ? (
                    <Spinner
                        label={`${humanizeToolName(tool.toolName)} is running`}
                        size={12}
                        tone="muted"
                        variant="circle"
                    />
                ) : (
                    <ToolIcon
                        glyph={toolGlyph(
                            tool.toolName,
                            presentation,
                            tool.failed || tool.status === "failed",
                        )}
                    />
                )}
            </span>
            <span
                className="happy-agent-activity__verb"
                data-happy-desktop-ui="agent-activity-verb"
            >
                <AgentActivityChangingText typed={verbTyped} value={verb} />
            </span>
            {stats ? (
                <span
                    className="happy-agent-activity__file-summary"
                    data-happy-desktop-ui="agent-activity-file-summary"
                >
                    <ScrollingText
                        className="happy-agent-activity__text"
                        data-happy-desktop-ui="agent-activity-text"
                    >
                        <AgentActivityChangingText
                            typeFirst={running}
                            typed={subjectTyped}
                            value={primaryText}
                        />
                    </ScrollingText>
                    {/* A side that changed nothing is left unsaid: "+0" is a
                        number the reader has to read before learning there was
                        nothing to learn. */}
                    {stats.added || stats.deleted ? (
                        <span
                            className="happy-agent-activity__stats"
                            data-happy-desktop-ui="agent-activity-stats"
                        >
                            {stats.added ? (
                                <span aria-hidden="true" className="happy-agent-activity__added">
                                    +{compactCount(stats.added)}
                                </span>
                            ) : null}
                            {stats.deleted ? (
                                <span aria-hidden="true" className="happy-agent-activity__deleted">
                                    &minus;{compactCount(stats.deleted)}
                                </span>
                            ) : null}
                            <span className="happy-visually-hidden">
                                {changeCountLabel(stats.added ?? 0, stats.deleted ?? 0)}
                            </span>
                        </span>
                    ) : null}
                </span>
            ) : (
                <ScrollingText
                    className="happy-agent-activity__text"
                    data-happy-desktop-ui="agent-activity-text"
                >
                    <AgentActivityChangingText
                        typeFirst={running}
                        typed={subjectTyped}
                        value={primaryText}
                    />
                </ScrollingText>
            )}
            {hasBody ? (
                <span aria-hidden="true" className="happy-agent-activity__chevron">
                    <Icon name={expanded ? "chevron-down" : "chevron-right"} size={14} />
                </span>
            ) : null}
            <AgentActivityTime time={props.time} />
        </>
    );

    // `data-review` marks a call that went through a permission review, and
    // `data-elevated` the reviewed call that then ran with temporary Full
    // access. Both sit on the row rather than on the review line so the mark
    // survives the single-line variant, where that line is cut.
    return (
        <div
            className="happy-agent-activity"
            data-status={tool.status}
            data-failed={tool.failed || tool.status === "failed" ? "" : undefined}
            data-tone={tone}
            data-presentation={presentation?.type ?? "generic"}
            data-review={tool.review ? "" : undefined}
            data-elevated={elevated ? "" : undefined}
            data-single-line={singleLine ? "" : undefined}
            data-expanded={expanded ? "" : undefined}
            data-happy-desktop-ui="agent-activity-call"
        >
            {/* The copy action is a sibling of the header rather than part of
                it: the header is itself a button in most variants, and a
                nested button would be neither valid nor clickable. */}
            <div className="happy-agent-activity__line" data-happy-desktop-ui="agent-activity-line">
                {singleLine && props.onSelect ? (
                    <button
                        className="happy-agent-activity__header"
                        data-happy-desktop-ui="agent-activity-header"
                        onClick={() => props.onSelect?.(tool)}
                        type="button"
                    >
                        {header}
                    </button>
                ) : singleLine ? (
                    <div
                        className="happy-agent-activity__header"
                        data-happy-desktop-ui="agent-activity-header"
                    >
                        {header}
                    </div>
                ) : (
                    <button
                        aria-expanded={hasBody ? (expanded ? "true" : "false") : undefined}
                        className="happy-agent-activity__header"
                        data-happy-desktop-ui="agent-activity-header"
                        disabled={!hasBody}
                        onClick={() => hasBody && setExpanded(!expanded)}
                        type="button"
                    >
                        {header}
                    </button>
                )}
                {filePath !== undefined && props.onFileOpen ? (
                    /* A sibling of the header for the same reason the copy
                       action is one: the header is itself a button in every
                       variant that opens something. */
                    <button
                        aria-label={`Open ${fileName(filePath)}`}
                        className="happy-agent-activity__open"
                        data-happy-desktop-ui="agent-activity-open"
                        data-path={filePath}
                        onClick={(event) => {
                            event.stopPropagation();
                            props.onFileOpen?.(filePath);
                        }}
                        type="button"
                    >
                        <Icon name="eye" size={14} />
                    </button>
                ) : null}
                {focused ? null : (
                    <CopyButton
                        data-happy-desktop-ui="agent-activity-copy"
                        label="Copy tool detail"
                        text={copyText}
                    />
                )}
            </div>

            {!singleLine && tool.review ? <PermissionReviewRow review={tool.review} /> : null}

            {!singleLine && genericResult !== undefined ? (
                <ChildRow tone={tool.failed ? "error" : "muted"}>{genericResult}</ChildRow>
            ) : null}

            {!singleLine && compactionFailure !== undefined ? (
                <ChildRow tone="error">{compactionFailure}</ChildRow>
            ) : null}

            {!singleLine && mcpResult ? (
                <div data-happy-desktop-ui="agent-activity-mcp-result">
                    {mcpResult.rows.map((row, index) => (
                        <ChildRow key={index} tone={tool.failed ? "error" : "muted"}>
                            {row || "\u00a0"}
                        </ChildRow>
                    ))}
                    {mcpResult.omitted > 0 ? <ChildRow>… {mcpResult.omitted} more</ChildRow> : null}
                </div>
            ) : null}

            {expanded && hasBody ? (
                <div
                    className="happy-agent-activity__body"
                    data-happy-desktop-ui="agent-activity-body"
                >
                    {presentation?.type === "fileDiff"
                        ? (() => {
                              const shown = presentation.files.slice(0, MAX_DIFF_FILES);
                              const omittedFiles =
                                  (presentation.omittedFiles ?? 0) +
                                  Math.max(0, presentation.files.length - MAX_DIFF_FILES);
                              return (
                                  <>
                                      {shown.map((file, index) => (
                                          <div
                                              className="happy-agent-activity__diff"
                                              key={`${file.path}-${index}`}
                                          >
                                              <DiffSnippet
                                                  file={file.path}
                                                  lines={diffLines(file)}
                                                  stats={{
                                                      added: diffCounts(file).added,
                                                      removed: diffCounts(file).deleted,
                                                  }}
                                              />
                                              {file.omittedLines ? (
                                                  <ChildRow>
                                                      … {file.omittedLines} more lines
                                                  </ChildRow>
                                              ) : null}
                                          </div>
                                      ))}
                                      {omittedFiles > 0 ? (
                                          <ChildRow>… {omittedFiles} more files</ChildRow>
                                      ) : null}
                                  </>
                              );
                          })()
                        : null}

                    {presentation?.type === "execCommand" && execOutput
                        ? (() => {
                              const headCount =
                                  execOutput.omitted > 0 ? EXEC_HEAD_TAIL : execOutput.lines.length;
                              return (
                                  <pre
                                      className="happy-agent-activity__output"
                                      data-happy-desktop-ui="agent-activity-output"
                                  >
                                      {execOutput.lines.map((line, index) => (
                                          <div
                                              className="happy-agent-activity__output-line"
                                              key={index}
                                          >
                                              {line || "\u00a0"}
                                              {execOutput.omitted > 0 && index === headCount - 1 ? (
                                                  <div className="happy-agent-activity__output-elide">
                                                      … +{execOutput.omitted} lines
                                                  </div>
                                              ) : null}
                                          </div>
                                      ))}
                                  </pre>
                              );
                          })()
                        : null}

                    {terminalInput ? (
                        <div className="happy-agent-activity__terminal">
                            {terminalInput.map((line, index) => (
                                <ChildRow key={index}>{line || "\u00a0"}</ChildRow>
                            ))}
                        </div>
                    ) : null}

                    {presentation?.type === "search"
                        ? presentation.sources?.map((source) => (
                              <ChildRow key={source.url}>
                                  <a
                                      className="happy-agent-activity__source"
                                      href={source.url}
                                      rel="noreferrer"
                                      target="_blank"
                                  >
                                      {source.title || source.url}
                                  </a>
                              </ChildRow>
                          ))
                        : null}

                    {argsPresent ? (
                        <pre
                            className="happy-agent-activity__args"
                            data-happy-desktop-ui="agent-activity-args"
                        >
                            {boundedJson(tool.arguments)}
                        </pre>
                    ) : null}
                </div>
            ) : null}
        </div>
    );
}

/** Model reasoning: one compact line that expands into the full thinking text. */
function AgentReasoningActivity(props: {
    text: string;
    streaming: boolean;
    defaultExpanded?: boolean;
    expanded?: boolean;
    onExpandedChange?: (expanded: boolean) => void;
    time?: string;
}) {
    const [expanded, setExpanded] = useExpansion(
        props.defaultExpanded ?? false,
        props.expanded,
        props.onExpandedChange,
    );
    const summary = props.text.split("\n").find((line) => line.trim().length > 0) ?? "";
    return (
        <div
            className="happy-agent-activity"
            data-expanded={expanded ? "" : undefined}
            data-presentation="reasoning"
            data-tone="warning"
            data-happy-desktop-ui="agent-activity-reasoning"
        >
            <button
                aria-expanded={expanded ? "true" : "false"}
                className="happy-agent-activity__header"
                data-happy-desktop-ui="agent-activity-header"
                onClick={() => setExpanded(!expanded)}
                type="button"
            >
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__dot"
                    data-tone={props.streaming ? "warning" : "success"}
                    data-happy-desktop-ui="agent-activity-dot"
                />
                <span
                    className="happy-agent-activity__verb"
                    data-happy-desktop-ui="agent-activity-verb"
                >
                    {props.streaming ? "Thinking" : "Thought"}
                </span>
                <ScrollingText
                    className="happy-agent-activity__text"
                    data-happy-desktop-ui="agent-activity-text"
                >
                    {summary}
                </ScrollingText>
                <span aria-hidden="true" className="happy-agent-activity__chevron">
                    <Icon name={expanded ? "chevron-down" : "chevron-right"} size={14} />
                </span>
                <AgentActivityTime time={props.time} />
            </button>
            {expanded ? (
                <div
                    className="happy-agent-activity__body happy-agent-activity__reasoning happy-message__body--markdown"
                    data-happy-desktop-ui="agent-activity-reasoning-body"
                >
                    {renderMessageMarkdown(props.text)}
                </div>
            ) : null}
        </div>
    );
}

/**
 * A message one agent sent another: who it came from on the row, and the
 * message itself behind it. The addressing envelope Happy Agent wrote for the
 * receiving model is part of the text and is shown with it rather than trimmed.
 */
function AgentMessageActivity(props: {
    agentId: string;
    agentName?: string;
    text: string;
    defaultExpanded?: boolean;
    expanded?: boolean;
    onExpandedChange?: (expanded: boolean) => void;
    time?: string;
}) {
    const [expanded, setExpanded] = useExpansion(
        props.defaultExpanded ?? false,
        props.expanded,
        props.onExpandedChange,
    );
    const disclosureAnchor = useMessageListDisclosureAnchor();
    const hasBody = props.text.trim().length > 0;
    return (
        <div
            className="happy-agent-activity"
            data-expanded={expanded ? "" : undefined}
            data-presentation="agent-message"
            data-tone="neutral"
            data-happy-desktop-ui="agent-activity-message"
        >
            <button
                aria-expanded={hasBody ? (expanded ? "true" : "false") : undefined}
                className="happy-agent-activity__header"
                data-happy-desktop-ui="agent-activity-header"
                disabled={!hasBody}
                onClick={(event) => {
                    if (!hasBody) return;
                    disclosureAnchor?.(event.currentTarget);
                    setExpanded(!expanded);
                }}
                type="button"
            >
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__glyph"
                    data-happy-desktop-ui="agent-activity-glyph"
                >
                    <Icon name="agents" size={12} />
                </span>
                <span
                    className="happy-agent-activity__verb"
                    data-happy-desktop-ui="agent-activity-verb"
                >
                    Message
                </span>
                <ScrollingText
                    className="happy-agent-activity__text"
                    data-happy-desktop-ui="agent-activity-text"
                >
                    from {props.agentName ?? props.agentId}
                </ScrollingText>
                {hasBody ? (
                    <span aria-hidden="true" className="happy-agent-activity__chevron">
                        <Icon name={expanded ? "chevron-down" : "chevron-right"} size={14} />
                    </span>
                ) : null}
                <AgentActivityTime time={props.time} />
            </button>
            {expanded && hasBody ? (
                <div
                    className="happy-agent-activity__body happy-agent-activity__message happy-message__body--markdown"
                    data-happy-desktop-ui="agent-activity-message-body"
                >
                    {renderMessageMarkdown(props.text)}
                </div>
            ) : null}
        </div>
    );
}

/** A shell-mode run: the command line, its exit state, and its captured output. */
function AgentShellActivity(props: {
    command: string;
    output: string;
    exitCode: number | null;
    running: boolean;
    timedOut: boolean;
    defaultExpanded?: boolean;
    expanded?: boolean;
    onExpandedChange?: (expanded: boolean) => void;
    time?: string;
}) {
    const [expanded, setExpanded] = useExpansion(
        props.defaultExpanded ?? true,
        props.expanded,
        props.onExpandedChange,
    );
    const failed = !props.running && (props.timedOut || (props.exitCode ?? 0) !== 0);
    const status = props.running
        ? "Running"
        : props.timedOut
          ? "Timed out"
          : `Exit ${props.exitCode ?? "?"}`;
    const hasBody = props.output.trim().length > 0;
    return (
        <div
            className="happy-agent-activity"
            data-expanded={expanded ? "" : undefined}
            data-presentation="shell"
            data-tone={props.running ? "warning" : failed ? "error" : "success"}
            data-happy-desktop-ui="agent-activity-shell"
        >
            <button
                aria-expanded={hasBody ? (expanded ? "true" : "false") : undefined}
                className="happy-agent-activity__header"
                data-happy-desktop-ui="agent-activity-header"
                disabled={!hasBody}
                onClick={() => hasBody && setExpanded(!expanded)}
                type="button"
            >
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__dot"
                    data-tone={props.running ? "warning" : failed ? "error" : "success"}
                    data-happy-desktop-ui="agent-activity-dot"
                />
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__glyph"
                    data-happy-desktop-ui="agent-activity-glyph"
                >
                    {failed ? (
                        <Octicon name="alert" size={12} />
                    ) : (
                        <Octicon name="code" size={12} />
                    )}
                </span>
                <span
                    className="happy-agent-activity__verb"
                    data-happy-desktop-ui="agent-activity-verb"
                >
                    Bash
                </span>
                <ScrollingText
                    className="happy-agent-activity__text"
                    data-happy-desktop-ui="agent-activity-text"
                >
                    {props.command}
                </ScrollingText>
                <span
                    className="happy-agent-activity__status"
                    data-failed={failed ? "true" : undefined}
                    data-happy-desktop-ui="agent-activity-status"
                >
                    {status}
                </span>
                {hasBody ? (
                    <span aria-hidden="true" className="happy-agent-activity__chevron">
                        <Icon name={expanded ? "chevron-down" : "chevron-right"} size={14} />
                    </span>
                ) : null}
                <AgentActivityTime time={props.time} />
            </button>
            {expanded && hasBody ? (
                <div
                    className="happy-agent-activity__body"
                    data-happy-desktop-ui="agent-activity-body"
                >
                    <pre
                        className="happy-agent-activity__output"
                        data-happy-desktop-ui="agent-activity-output"
                    >
                        {props.output}
                    </pre>
                </div>
            ) : null}
        </div>
    );
}

/**
 * A step the producer already described: its label and subject go straight to
 * the same single line a live tool call renders, so summarized and streamed
 * activity read identically.
 */
function AgentLabeledActivity(props: {
    label: string;
    subject?: string;
    status: ConversationActivityStatus;
    mono: boolean;
    time?: string;
}) {
    return (
        <div
            className="happy-agent-activity"
            data-happy-desktop-ui="agent-activity-call"
            data-mono={props.mono ? "" : undefined}
            data-single-line=""
            data-status={props.status}
            data-tone="neutral"
        >
            <div
                className="happy-agent-activity__header"
                data-happy-desktop-ui="agent-activity-header"
            >
                <span
                    className="happy-agent-activity__verb"
                    data-happy-desktop-ui="agent-activity-verb"
                >
                    <AgentActivityChangingText value={props.label} />
                </span>
                {props.subject !== undefined && props.subject.length > 0 ? (
                    <ScrollingText
                        className="happy-agent-activity__text"
                        data-happy-desktop-ui="agent-activity-text"
                    >
                        <AgentActivityChangingText value={props.subject} />
                    </ScrollingText>
                ) : null}
                <AgentActivityTime time={props.time} />
            </div>
        </div>
    );
}

/**
 * AgentActivityRow — the one glanceable row for everything an agent does inside
 * a conversation: a tool call, a reasoning block, a shell run, or a message
 * another agent sent it. Each variant shows its mark, a verb, and its subject on
 * a single line and expands to the detail on demand, so a long working turn
 * stays readable without hiding what happened. Presentational only: the caller
 * supplies the projected activity and the surface decides which rows to show at
 * all.
 */
export function AgentActivityRow(props: AgentActivityRowProps) {
    const activity = props.activity;
    return (
        <div
            className={["happy-agent-activity-row", props.className].filter(Boolean).join(" ")}
            data-happy-desktop-ui="agent-activity-row"
            data-kind={activity.kind}
            data-treatment={props.treatment ?? "detailed"}
            data-testid={props["data-testid"]}
            style={props.style}
        >
            {activity.kind === "tool" ? (
                <AgentToolActivity
                    defaultExpanded={props.defaultExpanded}
                    expanded={props.expanded}
                    motion={props.motion}
                    onExpandedChange={props.onExpandedChange}
                    treatment={props.treatment}
                    onSelect={props.onToolSelect}
                    {...(props.onFileOpen ? { onFileOpen: props.onFileOpen } : {})}
                    singleLine={props.singleLine}
                    time={props.time}
                    tool={activity.tool}
                />
            ) : activity.kind === "labeled" ? (
                <AgentLabeledActivity
                    label={activity.label}
                    mono={activity.mono}
                    status={activity.status}
                    subject={activity.subject}
                    time={props.time}
                />
            ) : activity.kind === "agentMessage" ? (
                <AgentMessageActivity
                    agentId={activity.agentId}
                    {...(activity.agentName === undefined ? {} : { agentName: activity.agentName })}
                    defaultExpanded={props.defaultExpanded}
                    expanded={props.expanded}
                    onExpandedChange={props.onExpandedChange}
                    text={activity.text}
                    time={props.time}
                />
            ) : activity.kind === "reasoning" ? (
                <AgentReasoningActivity
                    defaultExpanded={props.defaultExpanded}
                    expanded={props.expanded}
                    onExpandedChange={props.onExpandedChange}
                    streaming={activity.streaming}
                    text={activity.text}
                    time={props.time}
                />
            ) : (
                <AgentShellActivity
                    command={activity.command}
                    defaultExpanded={props.defaultExpanded}
                    expanded={props.expanded}
                    exitCode={activity.exitCode}
                    onExpandedChange={props.onExpandedChange}
                    output={activity.output}
                    running={activity.running}
                    timedOut={activity.timedOut}
                    time={props.time}
                />
            )}
        </div>
    );
}

packages/happy-desktop-ui/src/AgentActiv.newContent:
import { useState, type CSSProperties } from "react";
import type {
    ConversationActivity,
    ConversationActivityPresentation,
    ConversationAgentFace,
    ConversationActivityReview,
    ConversationActivityStatus,
    ConversationFileDiff,
    ConversationJson,
    ConversationToolCall,
} from "happy-desktop-state";
import { compactCount, changeCountLabel } from "./countText";
import { Avatar } from "./Avatar";
import { AvatarBrutalist } from "./AvatarBrutalist";
import { CopyButton } from "./CopyButton";
import { DiffSnippet, type DiffLine } from "./DiffSnippet";
import { filePreviewKind } from "./FilePreview";
import { Icon, type IconName } from "./Icon";
import { useMessageListDisclosureAnchor } from "./messageListDisclosureAnchor";
import { renderMessageMarkdown } from "./MessageMarkdown";
import { ScrollingText } from "./ScrollingText";
import { Spinner } from "./Spinner";
import { TypedText } from "./TypedText";
import { Ionicon, Octicon } from "./vectorIcons/VectorIcon";

/**
 * Which live labels type when their value changes. This affects animation
 * only: wording, timestamps, controls, and every other piece of row content
 * stay identical across profiles.
 */
export type ActivityMotion = "typewriter" | "verb-typed" | "calm-typed" | "calm";

/**
 * Content treatment independent of animation. `focused` keeps one action word
 * for the call's life, leaves copy metadata to the detail surface, and reveals
 * the tool's start time over the row's trailing edge.
 */
export type ActivityTreatment = "detailed" | "focused";

export type AgentActivityRowProps = {
    activity: ConversationActivity;
    /** Motion profile for live updates. Defaults to the historical `typewriter`. */
    motion?: ActivityMotion;
    /** Row content/chrome policy, independent of which labels animate. */
    treatment?: ActivityTreatment;
    /** Opens a tool's complete body in an owner-provided detail surface. */
    onToolSelect?: (tool: ConversationToolCall) => void;
    /**
     * Opens the workspace file a tool call worked on, in the product's file
     * viewer. A row whose tool names no single showable file offers nothing,
     * and a surface with no workspace behind it passes nothing.
     */
    onFileOpen?: (path: string) => void;
    /** Start expanded (blueprint/tests). Otherwise rich bodies collapse by default. */
    defaultExpanded?: boolean;
    /** Controlled disclosure state for a virtualized transcript row. */
    expanded?: boolean;
    /** Reports disclosure changes so an owner can rebuild modeled row geometry. */
    onExpandedChange?: (expanded: boolean) => void;
    /**
     * Local conversation tool rows: one neutral line aligned with agent text, with
     * no inline result or expand affordance.
     */
    singleLine?: boolean;
    /** Durable event time, revealed with the row's trailing hover metadata. */
    time?: string;
    className?: string;
    "data-testid"?: string;
    style?: CSSProperties;
};

/** Max file diffs rendered per tool before an overflow note replaces the rest. */
const MAX_DIFF_FILES = 5;
/** Head/tail line budget for exec-command output before the middle is elided. */
const EXEC_HEAD_TAIL = 5;
/** Bounded JSON budget for generic tool-call arguments (chars). */
const JSON_BUDGET = 4096;
/** MCP result-row budget: dim child rows shown before an overflow note (A3). */
const MCP_RESULT_ROWS = 5;

function useExpansion(
    defaultExpanded: boolean,
    expanded: boolean | undefined,
    onExpandedChange: ((expanded: boolean) => void) | undefined,
) {
    const [ownExpanded, setOwnExpanded] = useState(defaultExpanded);
    const value = expanded ?? ownExpanded;
    return [
        value,
        (next: boolean) => {
            if (expanded === undefined) setOwnExpanded(next);
            onExpandedChange?.(next);
        },
    ] as const;
}

function AgentActivityTime(props: { time?: string }) {
    return props.time ? (
        <span className="happy-agent-activity__time" data-happy-desktop-ui="agent-activity-time">
            {props.time}
        </span>
    ) : null;
}

/**
 * Parses an MCP tool name (`mcp__server__tool`) into its server and tool parts.
 * Returns undefined for any name that is not an MCP invocation, so the caller
 * falls back to the generic tool rendering path.
 */
function parseMcpToolName(name: string): { server: string; tool: string } | undefined {
    if (!name.startsWith("mcp__")) return undefined;
    const parts = name.split("__");
    if (parts.length < 3) return undefined;
    return { server: parts[1]!, tool: parts.slice(2).join(" ") };
}

/** Splits an MCP result into ≤`budget` dim rows, returning the overflow count. */
function mcpResultRows(display: string, budget: number): { rows: string[]; omitted: number } {
    const all = display.replace(/\n+$/, "").split("\n");
    if (all.length <= budget) return { rows: all, omitted: 0 };
    return { rows: all.slice(0, budget), omitted: all.length - budget };
}

/** Friendly tool label — mirrors the TUI `humanizeToolName` mapping (A3). */
function humanizeToolName(name: string): string {
    const explicit: Record<string, string> = {
        Agent: "Subagent",
        compact: "Context compaction",
        TaskInput: "Terminal input",
        TaskList: "Task list",
        TaskOutput: "Background output",
        spawn_agent: "Start subagent",
        wait_agent: "Wait for subagents",
        workflow: "Workflow",
        write_stdin: "Terminal input",
    };
    if (explicit[name]) return explicit[name]!;
    if (name.startsWith("mcp__")) {
        const parts = name.split("__");
        if (parts.length >= 3) return `${parts[1]} · ${parts.slice(2).join(" ")}`;
    }
    return name
        .replace(/[_-]+/g, " ")
        .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
        .replace(/\s+/g, " ")
        .trim()
        .replace(/^./, (character) => character.toUpperCase());
}

/**
 * Tools that type into a terminal that is already running, rather than starting
 * one. Matched by name for the window before the result arrives, when the row
 * has no presentation to classify it by.
 */
const TERMINAL_INPUT_TOOL = /stdin|terminal_?input|taskinput/;

/** Active/done verb for a tool by name + status (A2/A3). */
function toolVerb(
    name: string,
    status: ConversationActivityStatus,
    presentation?: ConversationActivityPresentation,
): string {
    if (presentation?.type === "agentSpawn") {
        if (status === "awaitingApproval") return "Awaiting approval to spawn";
        if (status === "failed") return "Failed to spawn";
        if (status === "stopped") return "Stopped spawning";
        return status === "running" ? "Spawning" : "Spawned";
    }
    if (status === "awaitingApproval") return "Awaiting approval";
    if (status === "stopped") return "Stopped";
    const active = status === "running";
    const lower = name.toLowerCase();
    if (presentation?.type === "compaction") {
        return status === "failed" ? "Failed" : active ? "Compacting" : "Compacted";
    }
    if (presentation?.type === "search") return active ? "Searching" : "Searched";
    if (presentation?.type === "exploration") return active ? "Exploring" : "Explored";
    // Typing into a terminal that is already running is not the same act as
    // starting one, and it is certainly not editing a file: `write_stdin` would
    // otherwise fall through to the write/edit family below and claim to have
    // edited something called "Write stdin".
    if (presentation?.type === "backgroundTerminalInteraction" || TERMINAL_INPUT_TOOL.test(lower))
        return active ? "Typing" : "Typed";
    // Waiting ends when a child sends input. That expected wake-up is projected
    // as success; the verb describes the wait rather than a generic tool use.
    if (lower === "wait_agent") return active ? "Waiting" : "Waited";
    if (presentation?.type === "execCommand" || /(bash|exec|shell|command|run)/.test(lower))
        return lower === "powershell" ? "PowerShell" : lower === "bash" ? "Bash" : "Shell";
    if (/(grep|find|glob|^ls$|list|search)/.test(lower)) return active ? "Exploring" : "Explored";
    if (/(read|view|cat|open)/.test(lower)) return active ? "Reading" : "Read";
    if (/(write|edit|patch|update|apply)/.test(lower)) return active ? "Editing" : "Edited";
    return active ? "Tool" : "Used";
}

/** Turns the lifecycle word into the stable action label used by focused rows. */
function toolVerbFocused(verb: string): string {
    switch (verb) {
        case "Exploring":
        case "Explored":
            return "Explore";
        case "Typing":
        case "Typed":
            return "Type";
        case "Reading":
            return "Read";
        case "Editing":
        case "Edited":
            return "Edit";
        case "Waiting":
        case "Waited":
            return "Wait";
        case "Used":
            return "Tool";
        default:
            return verb;
    }
}

/**
 * Tool → the glyph saying what kind of work it was. Commands use Octicons
 * `code`, failed tools use Octicons `alert`, and file edits use Ionicons
 * `document-outline`; the remaining tool families use the curated vocabulary.
 */
type ToolGlyph =
    | { set: "house"; name: IconName }
    | { set: "ionicons"; name: "document-outline" | "terminal-outline" }
    | { set: "octicons"; name: "alert" | "code" };

function toolGlyph(
    name: string,
    presentation: ConversationActivityPresentation | undefined,
    failed: boolean,
): ToolGlyph {
    if (failed) return { set: "octicons", name: "alert" };
    if (presentation?.type === "agentSpawn") return { set: "house", name: "agents" };
    if (presentation?.type === "compaction") return { set: "house", name: "filter" };
    if (presentation?.type === "search") return { set: "house", name: "globe" };
    if (presentation?.type === "exploration") return { set: "house", name: "search" };
    if (presentation?.type === "fileDiff") return { set: "ionicons", name: "document-outline" };
    const lower = name.toLowerCase();
    // Typing into a running terminal gets the terminal itself, so it is not
    // mistaken for the command that started one or for a file edit.
    if (presentation?.type === "backgroundTerminalInteraction" || TERMINAL_INPUT_TOOL.test(lower))
        return { set: "ionicons", name: "terminal-outline" };
    if (presentation?.type === "execCommand") return { set: "octicons", name: "code" };
    if (/(bash|exec|shell|command|run)/.test(lower)) return { set: "octicons", name: "code" };
    if (/(grep|find|glob|^ls$|list|search)/.test(lower)) return { set: "house", name: "search" };
    if (/(read|view|cat|open)/.test(lower)) return { set: "house", name: "doc" };
    if (/(write|edit|patch|update|apply)/.test(lower))
        return { set: "ionicons", name: "document-outline" };
    if (/(fetch|http|web|url|browser)/.test(lower)) return { set: "house", name: "globe" };
    if (/(task|todo|plan)/.test(lower)) return { set: "house", name: "tasks" };
    if (/(agent|spawn|subagent|workflow)/.test(lower)) return { set: "house", name: "agents" };
    return { set: "house", name: "zap" };
}

function ToolIcon(props: { glyph: ToolGlyph }) {
    if (props.glyph.set === "ionicons") return <Ionicon name={props.glyph.name} size={12} />;
    if (props.glyph.set === "octicons") return <Octicon name={props.glyph.name} size={12} />;
    return <Icon name={props.glyph.name} size={12} />;
}

/**
 * Retypes a tool label whenever this row's projected text changes.
 *
 * `typeFirst` also types the text the label opens with. A subject only retypes
 * when it changes, and whether a command ever changes is decided by the wire —
 * arguments that streamed in arrive as several values and type, the same
 * command delivered whole arrives once and does not. Rows that are live when
 * they appear ask for the first value to type too, so the same act looks the
 * same either way.
 */
function AgentActivityChangingText(props: { value: string; typed?: boolean; typeFirst?: boolean }) {
    return (props.typed ?? true) ? (
        <TypedText
            data-happy-desktop-ui="agent-activity-changing-text"
            {...(props.typeFirst ? { typeInitial: true } : {})}
            value={props.value}
        />
    ) : (
        <span
            className="happy-agent-activity__still-text"
            data-happy-desktop-ui="agent-activity-changing-text"
        >
            {props.value}
        </span>
    );
}

function explorationSummary(
    presentation: Extract<ConversationActivityPresentation, { type: "exploration" }>,
): string {
    const operations = presentation.operations;
    if (operations.every((operation) => operation.kind === "read")) {
        return [
            ...new Set(
                operations.flatMap((operation) =>
                    operation.kind === "read" ? [operation.name] : [],
                ),
            ),
        ].join(", ");
    }
    return operations
        .map((operation) => {
            if (operation.kind === "list") return `List ${operation.target}`;
            if (operation.kind === "read") return `Read ${operation.name}`;
            const detail =
                operation.query !== undefined && operation.path !== undefined
                    ? `${operation.query} in ${operation.path}`
                    : (operation.query ?? operation.path ?? operation.command);
            return `Search ${detail}`;
        })
        .join(" · ");
}

function compactionSummary(
    presentation: Extract<ConversationActivityPresentation, { type: "compaction" }>,
): string {
    const before = presentation.tokensBefore;
    const after = presentation.tokensAfter;
    if (before === undefined) {
        return after === undefined ? "context" : `context to ${contextTokenCount(after)} tokens`;
    }
    return after === undefined
        ? `context from ${contextTokenCount(before)} tokens`
        : `context ${contextTokenCount(before)} → ${contextTokenCount(after)} tokens`;
}

/** Context occupancy keeps one useful decimal deeper into the thousands than a file count. */
function contextTokenCount(tokens: number): string {
    if (tokens < 1_000) return String(Math.max(0, Math.round(tokens)));
    const thousands = tokens / 1_000;
    return `${thousands < 100 ? thousands.toFixed(1).replace(/\.0$/, "") : String(Math.round(thousands))}k`;
}

/** Status → semantic dot tone: warning while active/awaiting, error on stop/fail. */
function statusTone(status: ConversationActivityStatus): "success" | "warning" | "error" {
    if (status === "success") return "success";
    if (status === "failed" || status === "stopped") return "error";
    return "warning";
}

function diffVerb(kind: ConversationFileDiff["kind"]): string {
    if (kind === "add") return "Added";
    if (kind === "delete") return "Deleted";
    return "Edit";
}

/**
 * What was typed into a terminal, on one line. Terminal input is mostly control
 * characters and newlines, which paint as nothing at all: an interrupt would
 * otherwise be an empty row. Control codes are shown the way a terminal echoes
 * them, and a multi-line paste keeps its first line with the rest counted.
 */
function terminalInputSummary(input: string): string {
    const visible = input
        .replaceAll("\r\n", "\n")
        .replace(/\n+$/, "")
        // eslint-disable-next-line no-control-regex -- Terminal input is exactly where control codes arrive, and they must be made visible rather than filtered out.
        .replaceAll(/[\u0000-\u001F\u007F]/g, (character) =>
            character === "\n"
                ? "\n"
                : `^${String.fromCharCode(character.charCodeAt(0) ^ 0x40).toUpperCase()}`,
        );
    if (visible.length === 0) return "";
    const lines = visible.split("\n");
    return lines.length > 1 ? `${lines[0]!} … +${String(lines.length - 1)} lines` : lines[0]!;
}

function fileName(path: string): string {
    const normalized = path.replaceAll("\\", "/");
    return normalized.slice(normalized.lastIndexOf("/") + 1) || path;
}

/** Argument names the file-reading and file-writing tools carry a path under. */
const FILE_PATH_ARGUMENTS = ["file_path", "filePath", "path", "notebook_path"] as const;

/**
 * The one workspace file a tool call is about, when it is about exactly one and
 * Happy can show it. A multi-file edit has no single answer, and a tool whose
 * subject is an archive or a binary would only open on "no preview", so both
 * report nothing rather than offering a click that goes nowhere.
 */
function toolFilePath(tool: ConversationToolCall): string | undefined {
    const presentation = tool.presentation;
    const candidate =
        presentation?.type === "fileDiff"
            ? presentation.files.length === 1
                ? presentation.files[0]!.path
                : undefined
            : argumentFilePath(tool.arguments);
    if (candidate === undefined || candidate.trim().length === 0) return undefined;
    return filePreviewKind(candidate) === "binary" ? undefined : candidate;
}

function argumentFilePath(argumentsValue: ConversationToolCall["arguments"]): string | undefined {
    if (typeof argumentsValue !== "object" || argumentsValue === null) return undefined;
    if (Array.isArray(argumentsValue)) return undefined;
    for (const key of FILE_PATH_ARGUMENTS) {
        const value = (argumentsValue as Record<string, ConversationJson>)[key];
        if (typeof value === "string" && value.trim().length > 0) return value;
    }
    return undefined;
}

function diffCounts(file: ConversationFileDiff): { added: number; deleted: number } {
    if (file.added !== undefined || file.deleted !== undefined)
        return { added: file.added ?? 0, deleted: file.deleted ?? 0 };
    let added = 0;
    let deleted = 0;
    for (const hunk of file.hunks)
        for (const line of hunk.lines) {
            if (line.kind === "add") added += 1;
            else if (line.kind === "delete") deleted += 1;
        }
    return { added, deleted };
}

/** Flattens a file's hunks into numbered DiffSnippet lines with `@@` meta rows. */
function diffLines(file: ConversationFileDiff): DiffLine[] {
    const lines: DiffLine[] = [];
    file.hunks.forEach((hunk, index) => {
        if (file.hunks.length > 1 || index > 0)
            lines.push({
                kind: "meta",
                text: `@@ -${hunk.oldStart} +${hunk.newStart} @@`,
            });
        let oldLine = hunk.oldStart;
        let newLine = hunk.newStart;
        for (const line of hunk.lines) {
            if (line.kind === "add") {
                lines.push({ kind: "add", number: newLine, text: line.text });
                newLine += 1;
            } else if (line.kind === "delete") {
                lines.push({ kind: "del", number: oldLine, text: line.text });
                oldLine += 1;
            } else {
                lines.push({ kind: "context", number: newLine, text: line.text });
                oldLine += 1;
                newLine += 1;
            }
        }
    });
    return lines;
}

/** Keep the first and last `budget` lines, eliding the middle with a count note. */
function headTail(text: string, budget: number): { lines: string[]; omitted: number } {
    const all = text.replace(/\n+$/, "").split("\n");
    if (all.length <= budget * 2) return { lines: all, omitted: 0 };
    return {
        lines: [...all.slice(0, budget), ...all.slice(all.length - budget)],
        omitted: all.length - budget * 2,
    };
}

/**
 * Whether a tool's arguments have anything to show, answered without
 * serializing them. A call still being generated grows its arguments with every
 * frame of the stream, and the row only asks this to decide whether it can be
 * opened at all — so the question is settled from the shape rather than from a
 * string the row is about to throw away.
 */
function jsonPresent(value: ConversationJson): boolean {
    if (value === null) return false;
    if (Array.isArray(value)) return value.length > 0;
    if (typeof value === "object") return Object.keys(value).length > 0;
    return true;
}

function boundedJson(value: ConversationJson): string | undefined {
    if (!jsonPresent(value)) return undefined;
    const text = JSON.stringify(value, null, 2);
    return text.length > JSON_BUDGET ? `${text.slice(0, JSON_BUDGET)}\n… truncated` : text;
}

function ChildRow(props: { tone?: "muted" | "error"; children: React.ReactNode }) {
    return (
        <div
            className="happy-agent-activity__child"
            data-tone={props.tone ?? "muted"}
            data-happy-desktop-ui="agent-activity-child"
        >
            <span aria-hidden="true" className="happy-agent-activity__child-marker">
                └
            </span>
            <span
                className="happy-agent-activity__child-text"
                data-happy-desktop-ui="agent-activity-child-text"
            >
                {props.children}
            </span>
        </div>
    );
}

function PermissionReviewRow(props: { review: ConversationActivityReview }) {
    const { review } = props;
    const title =
        review.decision === "allow"
            ? "Approved"
            : review.decision === "deny"
              ? "Denied"
              : "Awaiting approval";
    return (
        <div className="happy-agent-activity__review" data-happy-desktop-ui="agent-activity-review">
            <span aria-hidden="true" className="happy-agent-activity__child-marker">
                └
            </span>
            <span className="happy-agent-activity__review-body">
                <span
                    className="happy-agent-activity__review-title"
                    data-happy-desktop-ui="agent-activity-review-title"
                >
                    {title} · {review.action}
                </span>
                <span className="happy-agent-activity__review-reason">{review.reason}</span>
                <span
                    className="happy-agent-activity__review-risk"
                    data-risk={review.risk}
                    data-happy-desktop-ui="agent-activity-review-risk"
                >
                    Risk: {review.risk}
                </span>
            </span>
        </div>
    );
}

/**
 * One tool invocation: a rich body chosen by `presentation` (file diff, exec
 * command, background-terminal interaction) with a generic header + result/args
 * fallback. A colored status dot and verb encode running/awaiting-approval/
 * success/failed/stopped, and a pending `review` renders an inline "Awaiting
 * approval" child line. Collapse/expand of the rich body is the only local UI
 * state; every value comes from props.
 */
function AgentToolActivity(props: {
    tool: ConversationToolCall;
    defaultExpanded?: boolean;
    expanded?: boolean;
    onExpandedChange?: (expanded: boolean) => void;
    motion?: ActivityMotion;
    treatment?: ActivityTreatment;
    onSelect?: (tool: ConversationToolCall) => void;
    onFileOpen?: (path: string) => void;
    singleLine?: boolean;
    time?: string;
}) {
    const { tool } = props;
    const presentation = tool.presentation;
    const [expanded, setExpanded] = useExpansion(
        props.defaultExpanded ?? false,
        props.expanded,
        props.onExpandedChange,
    );
    const singleLine = props.singleLine ?? false;
    const running = tool.status === "running";
    const motion = props.motion ?? "typewriter";
    const focused = props.treatment === "focused";
    const verbTyped = motion === "typewriter" || motion === "verb-typed";
    /** The subject types only in the profiles that type it. */
    const subjectTyped = motion === "typewriter" || motion === "calm-typed";

    const tone = singleLine ? "neutral" : statusTone(tool.status);

    // MCP tool calls (`mcp__server__tool`) have no protocol presentation; the TUI
    // derives their block at render time from the name, arguments, and result. We
    // do the same, but only when no richer presentation (diff/exec) applies.
    const mcp = presentation ? undefined : parseMcpToolName(tool.toolName);

    let primaryText: string;
    let stats: { added: number; deleted: number } | undefined;
    let verb: string;
    if (mcp) {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = `${mcp.server} · ${mcp.tool}`;
    } else if (presentation?.type === "agentSpawn") {
        verb = toolVerb(tool.toolName, tool.failed ? "failed" : tool.status, presentation);
        primaryText = presentation.model ? `${presentation.model.name} sub-agent` : "sub-agent";
    } else if (presentation?.type === "compaction") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = compactionSummary(presentation);
    } else if (presentation?.type === "search") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = presentation.query;
    } else if (presentation?.type === "exploration") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = explorationSummary(presentation);
    } else if (presentation?.type === "fileDiff") {
        const first = presentation.files[0];
        verb = first ? diffVerb(first.kind) : toolVerb(tool.toolName, tool.status, presentation);
        primaryText = first ? fileName(first.path) : humanizeToolName(tool.toolName);
        stats = presentation.files.reduce(
            (total, file) => {
                const counts = diffCounts(file);
                return {
                    added: total.added + counts.added,
                    deleted: total.deleted + counts.deleted,
                };
            },
            { added: 0, deleted: 0 },
        );
    } else if (presentation?.type === "execCommand") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText = presentation.command;
    } else if (presentation?.type === "backgroundTerminalInteraction") {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        // What was typed, not the command that started the terminal: several
        // interactions with one background task all carry the same command, so
        // showing that made a run of rows read as the same thing happening over
        // and over. The command is context, and it moves into the body below.
        primaryText = terminalInputSummary(presentation.input) || presentation.command;
    } else {
        verb = toolVerb(tool.toolName, tool.status, presentation);
        primaryText =
            tool.toolName.toLowerCase() === "wait_agent"
                ? "for subagents"
                : humanizeToolName(tool.toolName);
    }
    if (focused && presentation?.type !== "fileDiff") verb = toolVerbFocused(verb);
    /* Ran outside the sandbox. Said in colour alone — the whole line turns
       amber — because a word in the verb would push the command itself out of
       a row that is already short. A call that stopped or failed never got
       that far, and its own status is the louder fact. */
    const elevated =
        tool.elevated === true &&
        tool.status !== "stopped" &&
        tool.status !== "failed" &&
        !tool.failed;
    const filePath = props.onFileOpen ? toolFilePath(tool) : undefined;

    /* Only a row that is open, and open on its arguments, ever prints them.
       Serializing them anyway cost the whole argument tree on every frame of a
       call still being generated — for a transcript row that never shows a body
       at all, and for a closed row nobody has asked to see. */
    const argsPresent = presentation === undefined && jsonPresent(tool.arguments);
    const execOutput =
        presentation?.type === "execCommand"
            ? headTail(presentation.output, EXEC_HEAD_TAIL)
            : undefined;
    const terminalInput =
        presentation?.type === "backgroundTerminalInteraction"
            ? presentation.input.replace(/\n+$/, "").split("\n")
            : undefined;
    const compactionFailure =
        presentation?.type === "compaction" ? presentation.failureReason : undefined;

    /* What a reader reaches for the clipboard to get: the subject that scrolled
       out of the row, followed by the output or result the row only shows in
       part. Both are elided on screen, so the copy is the unabridged text. */
    const copyText = [
        primaryText,
        presentation?.type === "execCommand"
            ? presentation.output
            : presentation?.type === "search"
              ? presentation.sources?.map((source) => `${source.title}\n${source.url}`).join("\n")
              : presentation?.type === "compaction"
                ? presentation.failureReason
                : presentation === undefined
                  ? tool.display
                  : undefined,
    ]
        .map((part) => part?.replace(/\n+$/, ""))
        .filter((part): part is string => part !== undefined && part.length > 0)
        .join("\n");

    const hasBody = singleLine
        ? false
        : presentation?.type === "fileDiff"
          ? presentation.files.length > 0
          : presentation?.type === "search"
            ? (presentation.sources?.length ?? 0) > 0
            : presentation?.type === "execCommand"
              ? presentation.output.trim().length > 0
              : presentation?.type === "backgroundTerminalInteraction"
                ? presentation.input.trim().length > 0
                : argsPresent;

    // MCP results render as capped dim rows (≤5, then "… N more"); an interrupted
    // call collapses to a single "Interrupted." row, matching the TUI.
    const mcpResult = mcp
        ? tool.failure?.kind === "interrupted"
            ? { rows: ["Interrupted."], omitted: 0 }
            : tool.display && tool.display.trim().length > 0
              ? mcpResultRows(tool.display, MCP_RESULT_ROWS)
              : { rows: ["(empty result)"], omitted: 0 }
        : undefined;

    const genericResult =
        mcp || presentation
            ? undefined
            : tool.display !== undefined && tool.display.length > 0
              ? tool.display
              : "(empty result)";

    const header = (
        <>
            {singleLine ? null : (
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__dot"
                    data-tone={tone}
                    data-happy-desktop-ui="agent-activity-dot"
                />
            )}
            {/* What kind of work this was, told at a glance. It is decoration
                over the verb beside it, which already says the same thing in
                words, so it stays out of the accessibility tree. */}
            <span
                aria-hidden="true"
                className="happy-agent-activity__glyph"
                data-happy-desktop-ui="agent-activity-glyph"
            >
                {running ? (
                    <Spinner
                        label={`${humanizeToolName(tool.toolName)} is running`}
                        size={12}
                        tone="muted"
                        variant="circle"
                    />
                ) : (
                    <ToolIcon
                        glyph={toolGlyph(
                            tool.toolName,
                            presentation,
                            tool.failed || tool.status === "failed",
                        )}
                    />
                )}
            </span>
            <span
                className="happy-agent-activity__verb"
                data-happy-desktop-ui="agent-activity-verb"
            >
                <AgentActivityChangingText typed={verbTyped} value={verb} />
            </span>
            {stats ? (
                <span
                    className="happy-agent-activity__file-summary"
                    data-happy-desktop-ui="agent-activity-file-summary"
                >
                    <ScrollingText
                        className="happy-agent-activity__text"
                        data-happy-desktop-ui="agent-activity-text"
                    >
                        <AgentActivityChangingText
                            typeFirst={running}
                            typed={subjectTyped}
                            value={primaryText}
                        />
                    </ScrollingText>
                    {/* A side that changed nothing is left unsaid: "+0" is a
                        number the reader has to read before learning there was
                        nothing to learn. */}
                    {stats.added || stats.deleted ? (
                        <span
                            className="happy-agent-activity__stats"
                            data-happy-desktop-ui="agent-activity-stats"
                        >
                            {stats.added ? (
                                <span aria-hidden="true" className="happy-agent-activity__added">
                                    +{compactCount(stats.added)}
                                </span>
                            ) : null}
                            {stats.deleted ? (
                                <span aria-hidden="true" className="happy-agent-activity__deleted">
                                    &minus;{compactCount(stats.deleted)}
                                </span>
                            ) : null}
                            <span className="happy-visually-hidden">
                                {changeCountLabel(stats.added ?? 0, stats.deleted ?? 0)}
                            </span>
                        </span>
                    ) : null}
                </span>
            ) : (
                <ScrollingText
                    className="happy-agent-activity__text"
                    data-happy-desktop-ui="agent-activity-text"
                >
                    <AgentActivityChangingText
                        typeFirst={running}
                        typed={subjectTyped}
                        value={primaryText}
                    />
                </ScrollingText>
            )}
            {hasBody ? (
                <span aria-hidden="true" className="happy-agent-activity__chevron">
                    <Icon name={expanded ? "chevron-down" : "chevron-right"} size={14} />
                </span>
            ) : null}
            <AgentActivityTime time={props.time} />
        </>
    );

    // `data-review` marks a call that went through a permission review, and
    // `data-elevated` the reviewed call that then ran with temporary Full
    // access. Both sit on the row rather than on the review line so the mark
    // survives the single-line variant, where that line is cut.
    return (
        <div
            className="happy-agent-activity"
            data-status={tool.status}
            data-failed={tool.failed || tool.status === "failed" ? "" : undefined}
            data-tone={tone}
            data-presentation={presentation?.type ?? "generic"}
            data-review={tool.review ? "" : undefined}
            data-elevated={elevated ? "" : undefined}
            data-single-line={singleLine ? "" : undefined}
            data-expanded={expanded ? "" : undefined}
            data-happy-desktop-ui="agent-activity-call"
        >
            {/* The copy action is a sibling of the header rather than part of
                it: the header is itself a button in most variants, and a
                nested button would be neither valid nor clickable. */}
            <div className="happy-agent-activity__line" data-happy-desktop-ui="agent-activity-line">
                {singleLine && props.onSelect ? (
                    <button
                        className="happy-agent-activity__header"
                        data-happy-desktop-ui="agent-activity-header"
                        onClick={() => props.onSelect?.(tool)}
                        type="button"
                    >
                        {header}
                    </button>
                ) : singleLine ? (
                    <div
                        className="happy-agent-activity__header"
                        data-happy-desktop-ui="agent-activity-header"
                    >
                        {header}
                    </div>
                ) : (
                    <button
                        aria-expanded={hasBody ? (expanded ? "true" : "false") : undefined}
                        className="happy-agent-activity__header"
                        data-happy-desktop-ui="agent-activity-header"
                        disabled={!hasBody}
                        onClick={() => hasBody && setExpanded(!expanded)}
                        type="button"
                    >
                        {header}
                    </button>
                )}
                {filePath !== undefined && props.onFileOpen ? (
                    /* A sibling of the header for the same reason the copy
                       action is one: the header is itself a button in every
                       variant that opens something. */
                    <button
                        aria-label={`Open ${fileName(filePath)}`}
                        className="happy-agent-activity__open"
                        data-happy-desktop-ui="agent-activity-open"
                        data-path={filePath}
                        onClick={(event) => {
                            event.stopPropagation();
                            props.onFileOpen?.(filePath);
                        }}
                        type="button"
                    >
                        <Icon name="eye" size={14} />
                    </button>
                ) : null}
                {focused ? null : (
                    <CopyButton
                        data-happy-desktop-ui="agent-activity-copy"
                        label="Copy tool detail"
                        text={copyText}
                    />
                )}
            </div>

            {!singleLine && tool.review ? <PermissionReviewRow review={tool.review} /> : null}

            {!singleLine && genericResult !== undefined ? (
                <ChildRow tone={tool.failed ? "error" : "muted"}>{genericResult}</ChildRow>
            ) : null}

            {!singleLine && compactionFailure !== undefined ? (
                <ChildRow tone="error">{compactionFailure}</ChildRow>
            ) : null}

            {!singleLine && mcpResult ? (
                <div data-happy-desktop-ui="agent-activity-mcp-result">
                    {mcpResult.rows.map((row, index) => (
                        <ChildRow key={index} tone={tool.failed ? "error" : "muted"}>
                            {row || "\u00a0"}
                        </ChildRow>
                    ))}
                    {mcpResult.omitted > 0 ? <ChildRow>… {mcpResult.omitted} more</ChildRow> : null}
                </div>
            ) : null}

            {expanded && hasBody ? (
                <div
                    className="happy-agent-activity__body"
                    data-happy-desktop-ui="agent-activity-body"
                >
                    {presentation?.type === "fileDiff"
                        ? (() => {
                              const shown = presentation.files.slice(0, MAX_DIFF_FILES);
                              const omittedFiles =
                                  (presentation.omittedFiles ?? 0) +
                                  Math.max(0, presentation.files.length - MAX_DIFF_FILES);
                              return (
                                  <>
                                      {shown.map((file, index) => (
                                          <div
                                              className="happy-agent-activity__diff"
                                              key={`${file.path}-${index}`}
                                          >
                                              <DiffSnippet
                                                  file={file.path}
                                                  lines={diffLines(file)}
                                                  stats={{
                                                      added: diffCounts(file).added,
                                                      removed: diffCounts(file).deleted,
                                                  }}
                                              />
                                              {file.omittedLines ? (
                                                  <ChildRow>
                                                      … {file.omittedLines} more lines
                                                  </ChildRow>
                                              ) : null}
                                          </div>
                                      ))}
                                      {omittedFiles > 0 ? (
                                          <ChildRow>… {omittedFiles} more files</ChildRow>
                                      ) : null}
                                  </>
                              );
                          })()
                        : null}

                    {presentation?.type === "execCommand" && execOutput
                        ? (() => {
                              const headCount =
                                  execOutput.omitted > 0 ? EXEC_HEAD_TAIL : execOutput.lines.length;
                              return (
                                  <pre
                                      className="happy-agent-activity__output"
                                      data-happy-desktop-ui="agent-activity-output"
                                  >
                                      {execOutput.lines.map((line, index) => (
                                          <div
                                              className="happy-agent-activity__output-line"
                                              key={index}
                                          >
                                              {line || "\u00a0"}
                                              {execOutput.omitted > 0 && index === headCount - 1 ? (
                                                  <div className="happy-agent-activity__output-elide">
                                                      … +{execOutput.omitted} lines
                                                  </div>
                                              ) : null}
                                          </div>
                                      ))}
                                  </pre>
                              );
                          })()
                        : null}

                    {terminalInput ? (
                        <div className="happy-agent-activity__terminal">
                            {terminalInput.map((line, index) => (
                                <ChildRow key={index}>{line || "\u00a0"}</ChildRow>
                            ))}
                        </div>
                    ) : null}

                    {presentation?.type === "search"
                        ? presentation.sources?.map((source) => (
                              <ChildRow key={source.url}>
                                  <a
                                      className="happy-agent-activity__source"
                                      href={source.url}
                                      rel="noreferrer"
                                      target="_blank"
                                  >
                                      {source.title || source.url}
                                  </a>
                              </ChildRow>
                          ))
                        : null}

                    {argsPresent ? (
                        <pre
                            className="happy-agent-activity__args"
                            data-happy-desktop-ui="agent-activity-args"
                        >
                            {boundedJson(tool.arguments)}
                        </pre>
                    ) : null}
                </div>
            ) : null}
        </div>
    );
}

/** Model reasoning: one compact line that expands into the full thinking text. */
function AgentReasoningActivity(props: {
    text: string;
    streaming: boolean;
    defaultExpanded?: boolean;
    expanded?: boolean;
    onExpandedChange?: (expanded: boolean) => void;
    time?: string;
}) {
    const [expanded, setExpanded] = useExpansion(
        props.defaultExpanded ?? false,
        props.expanded,
        props.onExpandedChange,
    );
    const summary = props.text.split("\n").find((line) => line.trim().length > 0) ?? "";
    return (
        <div
            className="happy-agent-activity"
            data-expanded={expanded ? "" : undefined}
            data-presentation="reasoning"
            data-tone="warning"
            data-happy-desktop-ui="agent-activity-reasoning"
        >
            <button
                aria-expanded={expanded ? "true" : "false"}
                className="happy-agent-activity__header"
                data-happy-desktop-ui="agent-activity-header"
                onClick={() => setExpanded(!expanded)}
                type="button"
            >
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__dot"
                    data-tone={props.streaming ? "warning" : "success"}
                    data-happy-desktop-ui="agent-activity-dot"
                />
                <span
                    className="happy-agent-activity__verb"
                    data-happy-desktop-ui="agent-activity-verb"
                >
                    {props.streaming ? "Thinking" : "Thought"}
                </span>
                <ScrollingText
                    className="happy-agent-activity__text"
                    data-happy-desktop-ui="agent-activity-text"
                >
                    {summary}
                </ScrollingText>
                <span aria-hidden="true" className="happy-agent-activity__chevron">
                    <Icon name={expanded ? "chevron-down" : "chevron-right"} size={14} />
                </span>
                <AgentActivityTime time={props.time} />
            </button>
            {expanded ? (
                <div
                    className="happy-agent-activity__body happy-agent-activity__reasoning happy-message__body--markdown"
                    data-happy-desktop-ui="agent-activity-reasoning-body"
                >
                    {renderMessageMarkdown(props.text)}
                </div>
            ) : null}
        </div>
    );
}

/**
 * A message one agent sent another: who it came from on the row, and the
 * message itself behind it. The addressing envelope Happy Agent wrote for the
 * receiving model is part of the text and is shown with it rather than trimmed.
 */
function AgentMessageActivity(props: {
    agentId: string;
    agentName?: string;
    agentFace?: ConversationAgentFace;
    text: string;
    defaultExpanded?: boolean;
    expanded?: boolean;
    onExpandedChange?: (expanded: boolean) => void;
    time?: string;
}) {
    const [expanded, setExpanded] = useExpansion(
        props.defaultExpanded ?? false,
        props.expanded,
        props.onExpandedChange,
    );
    const disclosureAnchor = useMessageListDisclosureAnchor();
    const hasBody = props.text.trim().length > 0;
    return (
        <div
            className="happy-agent-activity"
            data-expanded={expanded ? "" : undefined}
            data-presentation="agent-message"
            data-tone="neutral"
            data-happy-desktop-ui="agent-activity-message"
        >
            <button
                aria-expanded={hasBody ? (expanded ? "true" : "false") : undefined}
                className="happy-agent-activity__header"
                data-happy-desktop-ui="agent-activity-header"
                disabled={!hasBody}
                onClick={(event) => {
                    if (!hasBody) return;
                    disclosureAnchor?.(event.currentTarget);
                    setExpanded(!expanded);
                }}
                title={props.agentName === undefined ? props.agentId : undefined}
                type="button"
            >
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__glyph"
                    data-happy-desktop-ui="agent-activity-glyph"
                >
                    {props.agentFace === undefined ? (
                        <Icon name="agents" size={12} />
                    ) : (
                        <AgentMessageFace face={props.agentFace} />
                    )}
                </span>
                <span
                    className="happy-agent-activity__verb"
                    data-happy-desktop-ui="agent-activity-verb"
                >
                    Message
                </span>
                <ScrollingText
                    className="happy-agent-activity__text"
                    data-happy-desktop-ui="agent-activity-text"
                >
                    from {props.agentName ?? agentIdShort(props.agentId)}
                </ScrollingText>
                {hasBody ? (
                    <span aria-hidden="true" className="happy-agent-activity__chevron">
                        <Icon name={expanded ? "chevron-down" : "chevron-right"} size={14} />
                    </span>
                ) : null}
                <AgentActivityTime time={props.time} />
            </button>
            {expanded && hasBody ? (
                <div
                    className="happy-agent-activity__body happy-agent-activity__message happy-message__body--markdown"
                    data-happy-desktop-ui="agent-activity-message-body"
                >
                    {renderMessageMarkdown(props.text)}
                </div>
            ) : null}
        </div>
    );
}

/** The edge of a sender's face: the glyph lane's own, so a face never moves the verb. */
const AGENT_MESSAGE_FACE_SIZE = 14;

/**
 * The sender's face, as its own row elsewhere pictures it, shrunk to the glyph
 * lane: a picture, initials, the tasks glyph, or the generated mark.
 */
function AgentMessageFace(props: { face: ConversationAgentFace }) {
    const face = props.face;
    if (face.kind === "generated")
        return <AvatarBrutalist id={face.seed} size={AGENT_MESSAGE_FACE_SIZE} />;
    return (
        <Avatar
            {...(face.kind === "image" ? { imageUrl: face.url } : {})}
            {...(face.kind === "task" ? { icon: "tasks" as const } : {})}
            initials={face.kind === "initials" ? face.initials : ""}
            size="xs"
            style={{
                borderRadius: 4,
                fontSize: 7,
                height: AGENT_MESSAGE_FACE_SIZE,
                width: AGENT_MESSAGE_FACE_SIZE,
            }}
            type="agent"
        />
    );
}

/**
 * An agent nobody here can name — deleted, or not visible to this reader — by
 * the start of its id: enough to tell two apart, short enough for one row. The
 * whole id stays in the message, where the receiving model replies to it, and
 * on the row's tooltip.
 */
function agentIdShort(agentId: string): string {
    return agentId.length > 10 ? `${agentId.slice(0, 8)}…` : agentId;
}

/** A shell-mode run: the command line, its exit state, and its captured output. */
function AgentShellActivity(props: {
    command: string;
    output: string;
    exitCode: number | null;
    running: boolean;
    timedOut: boolean;
    defaultExpanded?: boolean;
    expanded?: boolean;
    onExpandedChange?: (expanded: boolean) => void;
    time?: string;
}) {
    const [expanded, setExpanded] = useExpansion(
        props.defaultExpanded ?? true,
        props.expanded,
        props.onExpandedChange,
    );
    const failed = !props.running && (props.timedOut || (props.exitCode ?? 0) !== 0);
    const status = props.running
        ? "Running"
        : props.timedOut
          ? "Timed out"
          : `Exit ${props.exitCode ?? "?"}`;
    const hasBody = props.output.trim().length > 0;
    return (
        <div
            className="happy-agent-activity"
            data-expanded={expanded ? "" : undefined}
            data-presentation="shell"
            data-tone={props.running ? "warning" : failed ? "error" : "success"}
            data-happy-desktop-ui="agent-activity-shell"
        >
            <button
                aria-expanded={hasBody ? (expanded ? "true" : "false") : undefined}
                className="happy-agent-activity__header"
                data-happy-desktop-ui="agent-activity-header"
                disabled={!hasBody}
                onClick={() => hasBody && setExpanded(!expanded)}
                type="button"
            >
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__dot"
                    data-tone={props.running ? "warning" : failed ? "error" : "success"}
                    data-happy-desktop-ui="agent-activity-dot"
                />
                <span
                    aria-hidden="true"
                    className="happy-agent-activity__glyph"
                    data-happy-desktop-ui="agent-activity-glyph"
                >
                    {failed ? (
                        <Octicon name="alert" size={12} />
                    ) : (
                        <Octicon name="code" size={12} />
                    )}
                </span>
                <span
                    className="happy-agent-activity__verb"
                    data-happy-desktop-ui="agent-activity-verb"
                >
                    Bash
                </span>
                <ScrollingText
                    className="happy-agent-activity__text"
                    data-happy-desktop-ui="agent-activity-text"
                >
                    {props.command}
                </ScrollingText>
                <span
                    className="happy-agent-activity__status"
                    data-failed={failed ? "true" : undefined}
                    data-happy-desktop-ui="agent-activity-status"
                >
                    {status}
                </span>
                {hasBody ? (
                    <span aria-hidden="true" className="happy-agent-activity__chevron">
                        <Icon name={expanded ? "chevron-down" : "chevron-right"} size={14} />
                    </span>
                ) : null}
                <AgentActivityTime time={props.time} />
            </button>
            {expanded && hasBody ? (
                <div
                    className="happy-agent-activity__body"
                    data-happy-desktop-ui="agent-activity-body"
                >
                    <pre
                        className="happy-agent-activity__output"
                        data-happy-desktop-ui="agent-activity-output"
                    >
                        {props.output}
                    </pre>
                </div>
            ) : null}
        </div>
    );
}

/**
 * A step the producer already described: its label and subject go straight to
 * the same single line a live tool call renders, so summarized and streamed
 * activity read identically.
 */
function AgentLabeledActivity(props: {
    label: string;
    subject?: string;
    status: ConversationActivityStatus;
    mono: boolean;
    time?: string;
}) {
    return (
        <div
            className="happy-agent-activity"
            data-happy-desktop-ui="agent-activity-call"
            data-mono={props.mono ? "" : undefined}
            data-single-line=""
            data-status={props.status}
            data-tone="neutral"
        >
            <div
                className="happy-agent-activity__header"
                data-happy-desktop-ui="agent-activity-header"
            >
                <span
                    className="happy-agent-activity__verb"
                    data-happy-desktop-ui="agent-activity-verb"
                >
                    <AgentActivityChangingText value={props.label} />
                </span>
                {props.subject !== undefined && props.subject.length > 0 ? (
                    <ScrollingText
                        className="happy-agent-activity__text"
                        data-happy-desktop-ui="agent-activity-text"
                    >
                        <AgentActivityChangingText value={props.subject} />
                    </ScrollingText>
                ) : null}
                <AgentActivityTime time={props.time} />
            </div>
        </div>
    );
}

/**
 * AgentActivityRow — the one glanceable row for everything an agent does inside
 * a conversation: a tool call, a reasoning block, a shell run, or a message
 * another agent sent it. Each variant shows its mark, a verb, and its subject on
 * a single line and expands to the detail on demand, so a long working turn
 * stays readable without hiding what happened. Presentational only: the caller
 * supplies the projected activity and the surface decides which rows to show at
 * all.
 */
export function AgentActivityRow(props: AgentActivityRowProps) {
    const activity = props.activity;
    return (
        <div
            className={["happy-agent-activity-row", props.className].filter(Boolean).join(" ")}
            data-happy-desktop-ui="agent-activity-row"
            data-kind={activity.kind}
            data-treatment={props.treatment ?? "detailed"}
            data-testid={props["data-testid"]}
            style={props.style}
        >
            {activity.kind === "tool" ? (
                <AgentToolActivity
                    defaultExpanded={props.defaultExpanded}
                    expanded={props.expanded}
                    motion={props.motion}
                    onExpandedChange={props.onExpandedChange}
                    treatment={props.treatment}
                    onSelect={props.onToolSelect}
                    {...(props.onFileOpen ? { onFileOpen: props.onFileOpen } : {})}
                    singleLine={props.singleLine}
                    time={props.time}
                    tool={activity.tool}
                />
            ) : activity.kind === "labeled" ? (
                <AgentLabeledActivity
                    label={activity.label}
                    mono={activity.mono}
                    status={activity.status}
                    subject={activity.subject}
                    time={props.time}
                />
            ) : activity.kind === "agentMessage" ? (
                <AgentMessageActivity
                    agentId={activity.agentId}
                    {...(activity.agentName === undefined ? {} : { agentName: activity.agentName })}
                    {...(activity.agentFace === undefined ? {} : { agentFace: activity.agentFace })}
                    defaultExpanded={props.defaultExpanded}
                    expanded={props.expanded}
                    onExpandedChange={props.onExpandedChange}
                    text={activity.text}
                    time={props.time}
                />
            ) : activity.kind === "reasoning" ? (
                <AgentReasoningActivity
                    defaultExpanded={props.defaultExpanded}
                    expanded={props.expanded}
                    onExpandedChange={props.onExpandedChange}
                    streaming={activity.streaming}
                    text={activity.text}
                    time={props.time}
                />
            ) : (
                <AgentShellActivity
                    command={activity.command}
                    defaultExpanded={props.defaultExpanded}
                    expanded={props.expanded}
                    exitCode={activity.exitCode}
                    onExpandedChange={props.onExpandedChange}
                    output={activity.output}
                    running={activity.running}
                    timedOut={activity.timedOut}
                    time={props.time}
                />
            )}
        </div>
    );
}

